begin;

do $academy_lesson_complete$
declare
  target_lesson_id uuid;
begin
  select l.id into target_lesson_id
  from public.academy_lessons l
  join public.academy_modules m on m.id=l.module_id
  join public.academy_courses c on c.id=m.course_id
  where c.slug='introduction-to-the-world-of-perfumery' and l.slug='what-perfumery-really-is';
  if target_lesson_id is null then raise exception 'Target Academy lesson not found'; end if;

  update public.academy_lessons set status='draft', published_at=null, is_preview=false, reading_minutes=25, practice_minutes=15, updated_at=now() where id=target_lesson_id;

  update public.academy_lesson_block_translations bt
  set content=source.content, updated_at=now()
  from (values
      (1, 'en', $academy_complete${"heading":"A Formula Is Not Yet a Perfume","sections":[{"type":"heading","level":3,"text":"A Formula Is Not Yet a Perfume"},{"type":"paragraph","runs":[{"text":"On a perfumer’s table, there may be several small bottles, a scale, a collection of blotters, a notebook, and two formulas that appear almost identical."}]},{"type":"paragraph","runs":[{"text":"The difference between them may be very small. One material has been reduced. Another has been increased by a fraction. Yet when smelled, the results can feel noticeably different. One may seem heavier, while the other has more space. One may feel sweet and dense; the other, drier and more precise."}]},{"type":"paragraph","runs":[{"text":"A perfumer’s work does not begin when the first material is weighed. It does not end when every ingredient has been mixed."}]},{"type":"paragraph","runs":[{"text":"Before a formula is written, an idea must be translated. After the formula has been prepared, there is still smelling, waiting, comparing, recording, and revising."}]},{"type":"paragraph","runs":[{"text":"Perfumery is therefore not simply the act of combining pleasant-smelling materials. It is the practice of shaping an idea into an olfactory experience through materials, structure, evaluation, and deliberate decisions."}]}]}$academy_complete$::jsonb),
      (1, 'id', $academy_complete${"heading":"Sebuah Formula Belum Tentu Menjadi Parfum","sections":[{"type":"heading","level":3,"text":"Sebuah Formula Belum Tentu Menjadi Parfum"},{"type":"paragraph","runs":[{"text":"Di atas meja seorang perfumer terdapat beberapa botol kecil, timbangan, blotter, buku catatan, dan dua formula yang terlihat hampir sama."}]},{"type":"paragraph","runs":[{"text":"Perbedaan antara keduanya mungkin hanya sedikit. Satu material dikurangi. Material lain dinaikkan dalam jumlah yang sangat kecil. Namun ketika dicium, hasilnya dapat terasa berbeda: salah satunya lebih berat, sementara yang lain memiliki lebih banyak ruang. Salah satunya terasa manis dan padat, sementara yang lain lebih kering dan jelas."}]},{"type":"paragraph","runs":[{"text":"Pekerjaan seorang perfumer tidak dimulai ketika bahan pertama ditimbang. Pekerjaan itu juga tidak selesai ketika seluruh bahan telah tercampur."}]},{"type":"paragraph","runs":[{"text":"Sebelum formula dibuat, ada sebuah gagasan yang harus diterjemahkan. Setelah formula dibuat, masih ada proses mencium, menunggu, membandingkan, mencatat, dan memperbaiki."}]},{"type":"paragraph","runs":[{"text":"Karena itu, perfumery bukan sekadar kegiatan mencampurkan bahan yang harum. Perfumery adalah praktik membentuk sebuah gagasan menjadi pengalaman aroma melalui material, struktur, evaluasi, dan keputusan."}]}]}$academy_complete$::jsonb),
      (2, 'en', $academy_complete${"heading":"1. Perfumery Begins with Intention","sections":[{"type":"heading","level":2,"text":"1. Perfumery Begins with Intention"},{"type":"paragraph","runs":[{"text":"A perfume may begin with something very simple."}]},{"type":"paragraph","runs":[{"text":"A perfumer might receive a brief for a fresh citrus cologne, a soft vanilla skin scent, or a quiet woody fragrance. In these cases, the initial direction is relatively concrete."}]},{"type":"paragraph","runs":[{"text":"But a fragrance may also begin with something that has no obvious smell."}]},{"type":"paragraph","runs":[{"text":"For example:"}]},{"type":"bullet_list","items":["an empty room just before nightfall","laughter spreading beyond control","a garden after rainfall","someone who does not wish to be seen","a creature that feeds on the scent of sleeping people."]},{"type":"paragraph","runs":[{"text":"Within Indische Artisan and Indische World, a fragrance does not always begin with the question:"}]},{"type":"quote","runs":[{"text":"Which notes are currently popular?"}]},{"type":"paragraph","runs":[{"text":"It may begin with:"}]},{"type":"bullet_list","items":["Who is this character?","What do they desire?","What kind of place do they inhabit?","What has just happened there?","What scent remains after the event is over?"]},{"type":"paragraph","runs":[{"text":"Yet an interesting story is not a perfume."}]},{"type":"paragraph","runs":[{"text":"The story must still be translated into olfactory decisions."}]},{"type":"paragraph","runs":[{"text":"The perfumer must decide whether the idea feels bright or dark, cool or warm, weightless or heavy, transparent or dense. They must consider whether the fragrance should remain close to the skin or expand into the surrounding space. They must also decide whether it should feel familiar, strange, comforting, restrained, or slightly unsettling."}]},{"type":"paragraph","runs":[{"text":"An idea such as “an empty room before nightfall” can be interpreted in many ways."}]},{"type":"paragraph","runs":[{"text":"The room might feel:"}]},{"type":"bullet_list","items":["cold and clean","dusty and abandoned","softened by the smell of fabric","damp after rain","warm with the last remaining light","or unfamiliar, as though someone has just left."]},{"type":"paragraph","runs":[{"text":"Each interpretation requires a different material direction and a different structure."}]},{"type":"paragraph","runs":[{"text":"Creativity in perfumery is therefore not only the ability to imagine an evocative story. It is also the ability to make precise choices that allow the story to be smelled."}]},{"type":"heading","level":4,"text":"Common misconception"},{"type":"paragraph","runs":[{"text":"A strong concept automatically creates a strong perfume.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"A compelling concept can make a fragrance memorable, but it cannot replace structure. Even the most original idea still requires appropriate materials, balance, development, and disciplined evaluation."}]}]}$academy_complete$::jsonb),
      (2, 'id', $academy_complete${"heading":"1. Perfumery Dimulai dari Sebuah Maksud","sections":[{"type":"heading","level":2,"text":"1. Perfumery Dimulai dari Sebuah Maksud"},{"type":"paragraph","runs":[{"text":"Sebuah parfum dapat bermula dari sesuatu yang sangat sederhana."}]},{"type":"paragraph","runs":[{"text":"Seorang perfumer mungkin menerima brief untuk membuat citrus cologne yang segar, vanilla skin scent yang lembut, atau woody fragrance yang tenang. Dalam kasus seperti ini, arah awalnya cukup konkret."}]},{"type":"paragraph","runs":[{"text":"Namun sebuah parfum juga dapat dimulai dari sesuatu yang tidak memiliki aroma yang jelas."}]},{"type":"paragraph","runs":[{"text":"Misalnya:"}]},{"type":"bullet_list","items":["kamar kosong menjelang malam","suara tawa yang terus menyebar","kebun yang baru saja terkena hujan","seseorang yang tidak ingin terlihat","makhluk yang hidup dari aroma orang tertidur."]},{"type":"paragraph","runs":[{"text":"Di dalam Indische Artisan dan Indische World, sebuah parfum sering kali tidak dimulai dari pertanyaan, “Notes apa yang sedang populer?"}]},{"type":"paragraph","runs":[{"text":"Pertanyaannya dapat bermula dari:"}]},{"type":"bullet_list","items":["Siapa karakter ini?","Apa yang ia sukai?","Tempat seperti apa yang ia tinggali?","Apa yang baru saja terjadi di sana?","Aroma apa yang akan tertinggal setelah peristiwa itu?"]},{"type":"paragraph","runs":[{"text":"Namun cerita yang menarik belum menjadi parfum."}]},{"type":"paragraph","runs":[{"text":"Cerita tersebut masih harus diterjemahkan menjadi keputusan olfaktori."}]},{"type":"paragraph","runs":[{"text":"Perfumer perlu menentukan apakah gagasan itu terasa terang atau gelap, dingin atau hangat, ringan atau berat, transparan atau padat. Ia perlu memikirkan apakah parfum akan terasa dekat dengan kulit atau menyebar memenuhi ruang. Ia juga perlu menentukan apakah aromanya akan terasa familiar, aneh, menenangkan, atau sedikit mengganggu."}]},{"type":"paragraph","runs":[{"text":"Sebuah ide seperti “kamar kosong menjelang malam” dapat diterjemahkan menjadi banyak kemungkinan."}]},{"type":"paragraph","runs":[{"text":"Kamar itu bisa terasa:"}]},{"type":"bullet_list","items":["dingin dan bersih","berdebu dan ditinggalkan","lembut dengan aroma kain","lembap karena hujan","hangat karena cahaya terakhir","atau asing, seolah seseorang baru saja pergi."]},{"type":"paragraph","runs":[{"text":"Masing-masing kemungkinan membutuhkan arah material dan struktur yang berbeda."}]},{"type":"paragraph","runs":[{"text":"Karena itu, kreativitas dalam perfumery bukan hanya kemampuan menemukan cerita yang menarik. Kreativitas juga merupakan kemampuan untuk membuat keputusan yang tepat agar cerita tersebut dapat dicium."}]},{"type":"heading","level":4,"text":"Kesalahpahaman umum"},{"type":"paragraph","runs":[{"text":"Jika konsepnya kuat, parfumnya pasti kuat.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Konsep yang kuat dapat membuat sebuah parfum mudah diingat, tetapi konsep tidak dapat menggantikan struktur. Gagasan yang menarik tetap membutuhkan material yang tepat, keseimbangan, perkembangan, dan evaluasi yang disiplin."}]}]}$academy_complete$::jsonb),
      (3, 'en', $academy_complete${"title":"From Idea to Fragrance","steps":["Idea","Olfactory direction","Material selection","Formula structure","Evaluation","Modification","Finished fragrance"]}$academy_complete$::jsonb),
      (3, 'id', $academy_complete${"title":"Dari Gagasan Menuju Parfum","steps":["Gagasan","Arah olfaktori","Pemilihan material","Struktur formula","Evaluasi","Modifikasi","Finished fragrance"]}$academy_complete$::jsonb),
      (4, 'en', $academy_complete${"heading":"2. The Perfumer’s Palette","sections":[{"type":"heading","level":2,"text":"2. The Perfumer’s Palette"},{"type":"paragraph","runs":[{"text":"A painter works with colour. A perfumer works with fragrance materials."}]},{"type":"paragraph","runs":[{"text":"A perfumer’s palette may contain many types of materials, including essential oils, absolutes, extracts, isolates, synthetic aroma molecules, bases, and accords prepared for particular functions."}]},{"type":"paragraph","runs":[{"text":"Natural materials can be obtained from flowers, woods, resins, spices, fruit peels, and other natural sources through processes such as distillation and extraction. Synthetic aroma materials may be produced through chemical or biotechnological processes. They can expand the perfumer’s palette, support natural materials, or create effects that are difficult to obtain directly from nature."}]},{"type":"paragraph","runs":[{"text":"Inside a formula, every material has more than a smell."}]},{"type":"paragraph","runs":[{"text":"A material also has:"}]},{"type":"bullet_list","items":["strength","rate of development","texture","diffusion","persistence","character","and relationships with other materials."]},{"type":"paragraph","runs":[{"text":"A citrus oil, for example, may smell sparkling, juicy, bitter, bright, or peel-like. But its role is not limited to making a perfume “smell like citrus.” Citrus may open a composition, create energy, or provide contrast against darker materials."}]},{"type":"paragraph","runs":[{"text":"Woody materials may feel dry, warm, clean, rough, smooth, or spacious. Some help build structure or increase diffusion."}]},{"type":"paragraph","runs":[{"text":"Musk materials do not produce one single smell called “musk.” Depending on the material and its use, musk may create an impression of cleanliness, softness, warmth, airiness, skin, volume, or persistence."}]},{"type":"paragraph","runs":[{"text":"A perfumer therefore does not ask only:"}]},{"type":"quote","runs":[{"text":"Does this material smell good?"}]},{"type":"paragraph","runs":[{"text":"They also ask:"}]},{"type":"bullet_list","items":["What does this material do?","Does it open the formula or close it?","Does it soften something sharp?","Does it add volume?","Does it make another material easier to perceive?","Does it extend the drydown?","Does it hide something that should remain visible?"]},{"type":"heading","level":3,"text":"Natural and synthetic materials"},{"type":"paragraph","runs":[{"text":"Beginners often imagine natural materials as “real” and synthetic materials as “artificial."}]},{"type":"paragraph","runs":[{"text":"This distinction is too simple."}]},{"type":"paragraph","runs":[{"text":"Natural and synthetic materials are creative tools with different origins, functions, strengths, limitations, levels of consistency, and safety considerations."}]},{"type":"paragraph","runs":[{"text":"Natural materials are not automatically more refined, complex, safe, or long-lasting. Synthetic materials are not automatically harsher, cheaper, or less artistic."}]},{"type":"paragraph","runs":[{"text":"A natural material may contain a highly complex mixture of compounds and vary according to origin, harvest, season, and extraction method. A synthetic material may offer a precise character, greater consistency, better stability, or an effect that is not practically available from natural sources."}]},{"type":"paragraph","runs":[{"text":"Modern perfumery uses both."}]},{"type":"paragraph","runs":[{"text":"The important question is not which category is morally superior, but what each material contributes to the formula."}]},{"type":"heading","level":4,"text":"Common misconception"},{"type":"paragraph","runs":[{"text":"Natural materials are real, while synthetic materials are fake.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Both are real materials. Their differences relate to origin, method of production, composition, character, consistency, function, and use."}]}]}$academy_complete$::jsonb),
      (4, 'id', $academy_complete${"heading":"2. Palet Seorang Perfumer","sections":[{"type":"heading","level":2,"text":"2. Palet Seorang Perfumer"},{"type":"paragraph","runs":[{"text":"Seorang pelukis bekerja dengan warna. Seorang perfumer bekerja dengan fragrance materials."}]},{"type":"paragraph","runs":[{"text":"Palet seorang perfumer dapat berisi berbagai jenis material, termasuk essential oils, absolutes, extracts, isolates, synthetic aroma molecules, bases, serta accords yang telah dipersiapkan untuk fungsi tertentu."}]},{"type":"paragraph","runs":[{"text":"Material natural dapat diperoleh dari bunga, kayu, resin, rempah, kulit buah, dan sumber alam lain melalui proses seperti distillation atau extraction. Synthetic aroma materials dibuat melalui proses kimia atau bioteknologi dan dapat digunakan untuk memperluas palet perfumer, mendukung material natural, atau menciptakan efek yang sulit diperoleh langsung dari alam."}]},{"type":"paragraph","runs":[{"text":"Di dalam formula, setiap material memiliki lebih dari sekadar “bau”."}]},{"type":"paragraph","runs":[{"text":"Sebuah material juga memiliki:"}]},{"type":"bullet_list","items":["kekuatan","kecepatan perkembangan","tekstur","diffusion","persistence","karakter","serta hubungan dengan material lain."]},{"type":"paragraph","runs":[{"text":"Citrus oil, misalnya, dapat memberi kesan sparkling, juicy, bitter, bright, atau peel-like. Namun kehadirannya bukan hanya tentang membuat parfum “berbau jeruk”. Citrus dapat membantu membuka formula, memberikan energi, atau menciptakan kontras dengan bagian yang lebih gelap."}]},{"type":"paragraph","runs":[{"text":"Woody materials dapat memberikan kesan kering, hangat, bersih, kasar, lembut, atau luas. Beberapa di antaranya membantu membentuk struktur atau menambah diffusion."}]},{"type":"paragraph","runs":[{"text":"Musk materials juga tidak hanya menghasilkan satu aroma yang disebut “musk”. Bergantung pada jenis dan penggunaannya, musk dapat memberi efek bersih, lembut, hangat, airy, skin-like, atau memberi volume pada bagian lain dari formula."}]},{"type":"paragraph","runs":[{"text":"Karena itu, seorang perfumer tidak hanya bertanya:"}]},{"type":"quote","runs":[{"text":"Apakah material ini baunya enak?"}]},{"type":"paragraph","runs":[{"text":"Ia juga bertanya:"}]},{"type":"bullet_list","items":["Apa yang dilakukan material ini?","Apakah ia membuat formula lebih terbuka atau tertutup?","Apakah ia melembutkan bagian yang tajam?","Apakah ia memberi volume?","Apakah ia membuat bagian lain lebih terlihat?","Apakah ia memperpanjang drydown?","Apakah ia justru menutupi hal yang ingin dipertahankan?"]},{"type":"paragraph","runs":[{"text":"IFRA menggambarkan daftar material yang digunakan industri fragrance sebagai bagian dari “perfumer’s palette”. Palet ini mencakup material yang digunakan untuk membangun fragrance mixtures dalam berbagai jenis produk."}]},{"type":"heading","level":4,"text":"Natural dan synthetic"},{"type":"paragraph","runs":[{"text":"Pemula sering membayangkan natural sebagai bahan yang “asli”, sementara synthetic dianggap sebagai bahan “palsu”."}]},{"type":"paragraph","runs":[{"text":"Pembagian tersebut terlalu sederhana."}]},{"type":"paragraph","runs":[{"text":"Natural dan synthetic materials adalah alat kreatif dengan karakter, fungsi, keterbatasan, ketersediaan, dan kebutuhan keselamatan yang berbeda."}]},{"type":"paragraph","runs":[{"text":"Natural tidak selalu lebih halus, lebih kompleks, lebih aman, atau lebih tahan lama. Synthetic juga tidak selalu lebih kasar, lebih murah, atau kurang artistik."}]},{"type":"paragraph","runs":[{"text":"Sebuah material natural dapat memiliki komposisi yang kompleks dan berubah berdasarkan asal, musim, panen, atau proses ekstraksi. Sebuah synthetic material dapat memiliki karakter yang sangat spesifik, konsisten, stabil, atau memberi efek yang tidak tersedia secara praktis dari sumber alam."}]},{"type":"paragraph","runs":[{"text":"Perfumery modern menggunakan keduanya."}]},{"type":"paragraph","runs":[{"text":"Yang penting bukan memilih satu kubu, tetapi memahami apa yang dapat dilakukan setiap material di dalam formula."}]},{"type":"heading","level":4,"text":"Kesalahpahaman umum"},{"type":"paragraph","runs":[{"text":"Natural adalah bahan asli, sedangkan synthetic adalah bahan palsu.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Keduanya merupakan material nyata. Perbedaannya berkaitan dengan asal, cara produksi, komposisi, karakter, konsistensi, fungsi, serta cara penggunaannya."}]}]}$academy_complete$::jsonb),
      (5, 'en', $academy_complete${"title":"Materials Have Roles","sections":[{"type":"paragraph","runs":[{"text":"When smelling a material, do not ask only:"}]},{"type":"quote","runs":[{"text":"What does it smell like?"}]},{"type":"paragraph","runs":[{"text":"Begin asking:"}]},{"type":"quote","runs":[{"text":"What might this material do when placed beside other materials?"}]},{"type":"paragraph","runs":[{"text":"The second question brings you closer to the way a perfumer thinks."}]}]}$academy_complete$::jsonb),
      (5, 'id', $academy_complete${"title":"Material Memiliki Tugas","sections":[{"type":"paragraph","runs":[{"text":"Material memiliki tugas.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Saat mencium sebuah material, jangan hanya bertanya, “Baunya seperti apa?"}]},{"type":"paragraph","runs":[{"text":"Mulailah bertanya, “Apa yang mungkin dilakukan material ini ketika ditempatkan bersama material lain?"}]},{"type":"paragraph","runs":[{"text":"Pertanyaan kedua akan membawamu lebih dekat pada cara seorang perfumer berpikir."}]}]}$academy_complete$::jsonb),
      (6, 'en', $academy_complete${"heading":"3. A Formula Is a System of Relationships","sections":[{"type":"heading","level":2,"text":"3. A Formula Is a System of Relationships"},{"type":"paragraph","runs":[{"text":"Imagine that you have several materials that each smell interesting on their own."}]},{"type":"paragraph","runs":[{"text":"When combined, they will not necessarily produce a good perfume."}]},{"type":"paragraph","runs":[{"text":"Why?"}]},{"type":"paragraph","runs":[{"text":"Because a formula is not merely a collection of ingredients. It is a system of relationships."}]},{"type":"paragraph","runs":[{"text":"When one material is added, it does not only introduce its own smell. It can change how other materials are perceived."}]},{"type":"paragraph","runs":[{"text":"A material may:"}]},{"type":"bullet_list","items":["make another part feel brighter","reduce sweetness","cover a delicate detail","increase diffusion","add weight","create dryness","slow the development","or make the formula feel simpler."]},{"type":"paragraph","runs":[{"text":"Consider the idea of vanilla."}]},{"type":"paragraph","runs":[{"text":"Vanilla may feel creamy when combined with lactonic effects. It may become drier beside woods, smokier through phenolic facets, airier with musks, boozier beside rum-like effects, or fruitier when paired with plum and dried-fruit nuances."}]},{"type":"paragraph","runs":[{"text":"All of these fragrances may still be described as vanilla, but the experience they create can be entirely different."}]},{"type":"paragraph","runs":[{"text":"This is where the difference between theme and structure becomes important."}]},{"type":"paragraph","runs":[{"text":"A theme suggests the general direction. Structure determines how that direction is actually experienced."}]},{"type":"heading","level":3,"text":"An Indische Artisan example: Iron Banana"},{"type":"paragraph","runs":[{"text":"The name"},{"text":"Iron Banana","emphasis":true},{"text":"contains two seemingly clear ideas: banana and iron."}]},{"type":"paragraph","runs":[{"text":"Yet the name does not determine the final perfume."}]},{"type":"paragraph","runs":[{"text":"The perfumer must still decide:"}]},{"type":"bullet_list","items":["Is the banana ripe, green, creamy, candy-like, or artificial?","Is the iron cold, mineral, metallic, industrial, or blood-like?","Do banana and iron blend together?","Do they remain in conflict?","Which appears first?","Does the tension remain in the drydown?","Does the fragrance feel humorous, strange, aggressive, or unexpectedly comforting?"]},{"type":"paragraph","runs":[{"text":"These decisions matter more than simply ensuring that “banana” and “metal” can both be smelled."}]},{"type":"paragraph","runs":[{"text":"The same principle applies to any perfume."}]},{"type":"paragraph","runs":[{"text":"A rose fragrance is not defined only by the presence of rose. The important questions are what kind of rose it is, what surrounds it, what texture it has, where it appears to exist, and how it changes over time."}]},{"type":"heading","level":4,"text":"Common misconception"},{"type":"paragraph","runs":[{"text":"The more materials a formula contains, the more complex it becomes.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"The number of materials does not automatically determine depth."}]},{"type":"paragraph","runs":[{"text":"A relatively concise formula may feel rich and evolving when the relationships between its materials are clear. A formula with many materials may feel crowded yet directionless."}]},{"type":"paragraph","runs":[{"text":"Useful complexity comes from relationships, not quantity alone."}]}]}$academy_complete$::jsonb),
      (6, 'id', $academy_complete${"heading":"3. Formula Adalah Hubungan Antarbagian","sections":[{"type":"heading","level":2,"text":"3. Formula Adalah Hubungan Antarbagian"},{"type":"paragraph","runs":[{"text":"Bayangkan kamu memiliki beberapa material yang masing-masing terasa menarik ketika dicium sendiri."}]},{"type":"paragraph","runs":[{"text":"Ketika material-material tersebut dicampurkan, hasilnya belum tentu menjadi parfum yang baik."}]},{"type":"paragraph","runs":[{"text":"Mengapa?"}]},{"type":"paragraph","runs":[{"text":"Karena formula bukan sekadar kumpulan bahan. Formula adalah sistem hubungan."}]},{"type":"paragraph","runs":[{"text":"Ketika satu material ditambahkan, ia tidak hanya membawa aromanya sendiri. Ia dapat mengubah cara material lain dirasakan."}]},{"type":"paragraph","runs":[{"text":"Sebuah material dapat:"}]},{"type":"bullet_list","items":["membuat bagian lain terasa lebih terang","mengurangi kesan manis","menutup detail yang halus","memperluas diffusion","menambah berat","menciptakan kekeringan","memperlambat perkembangan","atau membuat formula terasa lebih sederhana."]},{"type":"paragraph","runs":[{"text":"Pertimbangkan sebuah gagasan vanilla."}]},{"type":"paragraph","runs":[{"text":"Vanilla dapat dibuat terasa creamy ketika dipertemukan dengan lactonic effects. Ia dapat terasa lebih kering ketika ditempatkan bersama woods. Ia dapat terasa smoky ketika diberi phenolic facets, airy ketika diperluas dengan musks, boozy ketika dipasangkan dengan rum-like effects, atau lebih fruity ketika bertemu plum dan dried-fruit nuances."}]},{"type":"paragraph","runs":[{"text":"Kita masih dapat menyebut semuanya sebagai “vanilla”, tetapi pengalaman yang dihasilkan bisa sangat berbeda."}]},{"type":"paragraph","runs":[{"text":"Di sinilah perbedaan antara tema dan struktur menjadi penting."}]},{"type":"paragraph","runs":[{"text":"Tema memberi tahu kita arah umum. Struktur menentukan bagaimana arah itu benar-benar hadir."}]},{"type":"heading","level":3,"text":"Contoh dari Indische Artisan: Iron Banana"},{"type":"paragraph","runs":[{"text":"Nama"},{"text":"Iron Banana","emphasis":true},{"text":"mengandung dua gagasan yang tampak jelas: banana dan iron."}]},{"type":"paragraph","runs":[{"text":"Namun nama tersebut belum menjelaskan parfum akhirnya."}]},{"type":"paragraph","runs":[{"text":"Perfumer masih harus menentukan:"}]},{"type":"bullet_list","items":["Apakah banana terasa matang, hijau, creamy, candy-like, atau artificial?","Apakah iron terasa dingin, mineral, metallic, industrial, atau seperti darah?","Apakah banana dan iron menyatu?","Apakah keduanya saling bertabrakan?","Mana yang muncul lebih dahulu?","Apakah drydown masih mempertahankan ketegangan itu?","Apakah parfum terasa lucu, asing, agresif, atau justru nyaman?"]},{"type":"paragraph","runs":[{"text":"Keputusan-keputusan tersebut jauh lebih penting daripada sekadar memastikan bahwa “banana” dan “metallic” dapat tercium."}]},{"type":"paragraph","runs":[{"text":"Hal yang sama berlaku untuk parfum apa pun."}]},{"type":"paragraph","runs":[{"text":"Sebuah rose fragrance bukan hanya tentang kehadiran rose. Pertanyaannya adalah rose seperti apa, berada di ruang seperti apa, ditemani oleh apa, memiliki tekstur seperti apa, dan bagaimana ia berubah sepanjang waktu."}]},{"type":"heading","level":4,"text":"Kesalahpahaman umum"},{"type":"paragraph","runs":[{"text":"Semakin banyak material, semakin kompleks parfumnya.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Jumlah material tidak otomatis menentukan kedalaman sebuah parfum."}]},{"type":"paragraph","runs":[{"text":"Formula yang relatif ringkas dapat terasa kaya dan berkembang dengan baik jika hubungan antar-materialnya jelas. Sebaliknya, formula yang berisi banyak material dapat terasa penuh tetapi tidak memiliki arah."}]},{"type":"paragraph","runs":[{"text":"Kompleksitas yang berguna datang dari hubungan, bukan sekadar jumlah."}]}]}$academy_complete$::jsonb),
      (7, 'en', $academy_complete${"title":"A Material Can Affect More Than Smell","center":"Material","nodes":["Texture","Diffusion","Contrast","Development","Persistence","Balance"]}$academy_complete$::jsonb),
      (7, 'id', $academy_complete${"title":"Material Memengaruhi Lebih dari Sekadar Bau","center":"Material","nodes":["Tekstur","Diffusion","Kontras","Perkembangan","Persistence","Keseimbangan"]}$academy_complete$::jsonb),
      (8, 'en', $academy_complete${"heading":"4. Creation Happens Through Modification","sections":[{"type":"heading","level":2,"text":"4. Creation Happens Through Modification"},{"type":"paragraph","runs":[{"text":"In popular imagination, a gifted perfumer may appear to discover the final formula in a single attempt."}]},{"type":"paragraph","runs":[{"text":"In practice, creation often develops through modification."}]},{"type":"paragraph","runs":[{"text":"One idea may produce many versions:"}]},{"type":"bullet_list","items":["Modification 01","Modification 02","Modification 03","Modification 04"]},{"type":"paragraph","runs":[{"text":"The differences between them may be small."}]},{"type":"paragraph","runs":[{"text":"One version may reduce sweetness. Another may attempt to increase diffusion. A later modification may clean the opening, soften harshness, give more space to the heart, or extend the drydown."}]},{"type":"paragraph","runs":[{"text":"Each modification asks a question."}]},{"type":"quote","runs":[{"text":"What happens if this part is reduced?"}]},{"type":"quote","runs":[{"text":"What happens if the structure is made lighter?"}]},{"type":"quote","runs":[{"text":"Is the central idea still clear after three hours?"}]},{"type":"quote","runs":[{"text":"Does the most interesting part disappear when the formula becomes smoother?"}]},{"type":"paragraph","runs":[{"text":"The process can be represented as a cycle:"}]},{"type":"paragraph","runs":[{"text":"Compose","emphasis":true},{"text":"→"},{"text":"Smell","emphasis":true},{"text":"→"},{"text":"Wait","emphasis":true},{"text":"→"},{"text":"Compare","emphasis":true},{"text":"→"},{"text":"Record","emphasis":true},{"text":"→"},{"text":"Modify","emphasis":true},{"text":"→"},{"text":"Smell again","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Waiting is an essential part of this process."}]},{"type":"paragraph","runs":[{"text":"A formula may feel sharp during the first few minutes and become balanced later. Another may have a compelling opening but lose direction after an hour."}]},{"type":"paragraph","runs":[{"text":"Decisions should therefore not be based only on first impressions."}]},{"type":"paragraph","runs":[{"text":"A perfumer smells at several stages, compares modifications on separate blotters, and records observations consistently."}]},{"type":"paragraph","runs":[{"text":"Notes reduce dependence on memory. They also help reveal patterns: which changes worked, what disappeared, and what continues to create problems."}]},{"type":"heading","level":4,"text":"Common misconception"},{"type":"paragraph","runs":[{"text":"Natural materials are real, while synthetic materials are fake.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Both are real materials. Their differences relate to origin, method of production, composition, character, consistency, function, and use."}]},{"type":"heading","level":2,"text":"3. A Formula Is a System of Relationships"},{"type":"paragraph","runs":[{"text":"Imagine that you have several materials that each smell interesting on their own."}]},{"type":"paragraph","runs":[{"text":"When combined, they will not necessarily produce a good perfume."}]},{"type":"paragraph","runs":[{"text":"Why?"}]},{"type":"paragraph","runs":[{"text":"Because a formula is not merely a collection of ingredients. It is a system of relationships."}]},{"type":"paragraph","runs":[{"text":"When one material is added, it does not only introduce its own smell. It can change how other materials are perceived."}]},{"type":"paragraph","runs":[{"text":"A material may:"}]},{"type":"bullet_list","items":["make another part feel brighter","reduce sweetness","cover a delicate detail","increase diffusion","add weight","create dryness","slow the development","or make the formula feel simpler."]},{"type":"paragraph","runs":[{"text":"Consider the idea of vanilla."}]},{"type":"paragraph","runs":[{"text":"Vanilla may feel creamy when combined with lactonic effects. It may become drier beside woods, smokier through phenolic facets, airier with musks, boozier beside rum-like effects, or fruitier when paired with plum and dried-fruit nuances."}]},{"type":"paragraph","runs":[{"text":"All of these fragrances may still be described as vanilla, but the experience they create can be entirely different."}]},{"type":"paragraph","runs":[{"text":"This is where the difference between theme and structure becomes important."}]},{"type":"paragraph","runs":[{"text":"A theme suggests the general direction. Structure determines how that direction is actually experienced."}]},{"type":"heading","level":3,"text":"An Indische Artisan example: Iron Banana"},{"type":"paragraph","runs":[{"text":"The name"},{"text":"Iron Banana","emphasis":true},{"text":"contains two seemingly clear ideas: banana and iron."}]},{"type":"paragraph","runs":[{"text":"Yet the name does not determine the final perfume."}]},{"type":"paragraph","runs":[{"text":"The perfumer must still decide:"}]},{"type":"bullet_list","items":["Is the banana ripe, green, creamy, candy-like, or artificial?","Is the iron cold, mineral, metallic, industrial, or blood-like?","Do banana and iron blend together?","Do they remain in conflict?","Which appears first?","Does the tension remain in the drydown?","Does the fragrance feel humorous, strange, aggressive, or unexpectedly comforting?"]},{"type":"paragraph","runs":[{"text":"These decisions matter more than simply ensuring that “banana” and “metal” can both be smelled."}]},{"type":"paragraph","runs":[{"text":"The same principle applies to any perfume."}]},{"type":"paragraph","runs":[{"text":"A rose fragrance is not defined only by the presence of rose. The important questions are what kind of rose it is, what surrounds it, what texture it has, where it appears to exist, and how it changes over time."}]},{"type":"heading","level":4,"text":"Common misconception"},{"type":"paragraph","runs":[{"text":"The more materials a formula contains, the more complex it becomes.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"The number of materials does not automatically determine depth."}]},{"type":"paragraph","runs":[{"text":"A relatively concise formula may feel rich and evolving when the relationships between its materials are clear. A formula with many materials may feel crowded yet directionless."}]},{"type":"paragraph","runs":[{"text":"Useful complexity comes from relationships, not quantity alone."}]},{"type":"heading","level":2,"text":"4. Creation Happens Through Modification"},{"type":"paragraph","runs":[{"text":"In popular imagination, a gifted perfumer may appear to discover the final formula in a single attempt."}]},{"type":"paragraph","runs":[{"text":"In practice, creation often develops through modification."}]},{"type":"paragraph","runs":[{"text":"One idea may produce many versions:"}]},{"type":"bullet_list","items":["Modification 01","Modification 02","Modification 03","Modification 04"]},{"type":"paragraph","runs":[{"text":"The differences between them may be small."}]},{"type":"paragraph","runs":[{"text":"One version may reduce sweetness. Another may attempt to increase diffusion. A later modification may clean the opening, soften harshness, give more space to the heart, or extend the drydown."}]},{"type":"paragraph","runs":[{"text":"Each modification asks a question."}]},{"type":"quote","runs":[{"text":"What happens if this part is reduced?"}]},{"type":"quote","runs":[{"text":"What happens if the structure is made lighter?"}]},{"type":"quote","runs":[{"text":"Is the central idea still clear after three hours?"}]},{"type":"quote","runs":[{"text":"Does the most interesting part disappear when the formula becomes smoother?"}]},{"type":"paragraph","runs":[{"text":"The process can be represented as a cycle:"}]},{"type":"paragraph","runs":[{"text":"Compose","emphasis":true},{"text":"→"},{"text":"Smell","emphasis":true},{"text":"→"},{"text":"Wait","emphasis":true},{"text":"→"},{"text":"Compare","emphasis":true},{"text":"→"},{"text":"Record","emphasis":true},{"text":"→"},{"text":"Modify","emphasis":true},{"text":"→"},{"text":"Smell again","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Waiting is an essential part of this process."}]},{"type":"paragraph","runs":[{"text":"A formula may feel sharp during the first few minutes and become balanced later. Another may have a compelling opening but lose direction after an hour."}]},{"type":"paragraph","runs":[{"text":"Decisions should therefore not be based only on first impressions."}]},{"type":"paragraph","runs":[{"text":"A perfumer smells at several stages, compares modifications on separate blotters, and records observations consistently."}]},{"type":"paragraph","runs":[{"text":"Notes reduce dependence on memory. They also help reveal patterns: which changes worked, what disappeared, and what continues to create problems."}]},{"type":"heading","level":3,"text":"Perfumer’s Note"},{"type":"heading","level":4,"text":"Do Not Judge Too Quickly"},{"type":"paragraph","runs":[{"text":"The opening is often the easiest part to notice, but it is not always the most important."}]},{"type":"paragraph","runs":[{"text":"Give the formula time to reveal its structure. Some problems only become visible after the most volatile materials begin to fade."}]},{"type":"heading","level":4,"text":"Common misconception"},{"type":"paragraph","runs":[{"text":"Modification means that the previous formula failed.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Not necessarily."}]},{"type":"paragraph","runs":[{"text":"Modification is a method of understanding a formula. Even a version that is never selected can reveal boundaries, possibilities, and directions that were previously hidden."}]}]}$academy_complete$::jsonb),
      (8, 'id', $academy_complete${"heading":"4. Penciptaan Terjadi Melalui Modifikasi","sections":[{"type":"heading","level":2,"text":"4. Penciptaan Terjadi Melalui Modifikasi"},{"type":"paragraph","runs":[{"text":"Dalam imajinasi populer, perfumer yang berbakat mungkin digambarkan menemukan formula final dalam satu kali percobaan."}]},{"type":"paragraph","runs":[{"text":"Dalam praktiknya, penciptaan sering berlangsung melalui modifikasi."}]},{"type":"paragraph","runs":[{"text":"Satu ide dapat menghasilkan banyak versi:"}]},{"type":"bullet_list","items":["Modification 01","Modification 02","Modification 03","Modification 04"]},{"type":"paragraph","runs":[{"text":"Perbedaan antarversi tidak selalu besar."}]},{"type":"paragraph","runs":[{"text":"Satu versi mungkin mengurangi sweetness. Versi lain mencoba meningkatkan diffusion. Modifikasi berikutnya mungkin membersihkan opening, mengurangi harshness, memberi lebih banyak ruang pada heart, atau memperpanjang drydown."}]},{"type":"paragraph","runs":[{"text":"Setiap modifikasi adalah sebuah pertanyaan."}]},{"type":"quote","runs":[{"text":"Apa yang terjadi jika bagian ini dikurangi?"}]},{"type":"quote","runs":[{"text":"Apa yang terjadi jika struktur dibuat lebih ringan?"}]},{"type":"quote","runs":[{"text":"Apakah kesan utama masih terbaca setelah tiga jam?"}]},{"type":"quote","runs":[{"text":"Apakah bagian yang menarik justru hilang ketika formula dibuat lebih halus?"}]},{"type":"paragraph","runs":[{"text":"Prosesnya dapat digambarkan sebagai lingkaran:"}]},{"type":"paragraph","runs":[{"text":"Compose","emphasis":true},{"text":"→"},{"text":"Smell","emphasis":true},{"text":"→"},{"text":"Wait","emphasis":true},{"text":"→"},{"text":"Compare","emphasis":true},{"text":"→"},{"text":"Record","emphasis":true},{"text":"→"},{"text":"Modify","emphasis":true},{"text":"→"},{"text":"Smell again","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Menunggu adalah bagian penting dari proses ini."}]},{"type":"paragraph","runs":[{"text":"Sebuah formula dapat terasa tajam pada menit pertama, lalu menjadi seimbang setelah beberapa waktu. Formula lain mungkin memiliki opening yang menarik, tetapi kehilangan arah setelah satu jam."}]},{"type":"paragraph","runs":[{"text":"Karena itu, keputusan tidak sebaiknya dibuat hanya dari kesan pertama."}]},{"type":"paragraph","runs":[{"text":"Perfumer perlu mencium pada beberapa tahap, membandingkan modifikasi pada blotter yang berbeda, dan mencatat perubahan secara konsisten."}]},{"type":"paragraph","runs":[{"text":"Catatan membantu mengurangi ketergantungan pada ingatan. Ia juga membantu perfumer melihat pola: perubahan apa yang berhasil, apa yang menghilang, dan apa yang terus menjadi masalah."}]},{"type":"heading","level":4,"text":"Kesalahpahaman umum"},{"type":"paragraph","runs":[{"text":"Natural adalah bahan asli, sedangkan synthetic adalah bahan palsu.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Keduanya merupakan material nyata. Perbedaannya berkaitan dengan asal, cara produksi, komposisi, karakter, konsistensi, fungsi, serta cara penggunaannya."}]},{"type":"heading","level":2,"text":"3. Formula Adalah Hubungan Antarbagian"},{"type":"paragraph","runs":[{"text":"Bayangkan kamu memiliki beberapa material yang masing-masing terasa menarik ketika dicium sendiri."}]},{"type":"paragraph","runs":[{"text":"Ketika material-material tersebut dicampurkan, hasilnya belum tentu menjadi parfum yang baik."}]},{"type":"paragraph","runs":[{"text":"Mengapa?"}]},{"type":"paragraph","runs":[{"text":"Karena formula bukan sekadar kumpulan bahan. Formula adalah sistem hubungan."}]},{"type":"paragraph","runs":[{"text":"Ketika satu material ditambahkan, ia tidak hanya membawa aromanya sendiri. Ia dapat mengubah cara material lain dirasakan."}]},{"type":"paragraph","runs":[{"text":"Sebuah material dapat:"}]},{"type":"bullet_list","items":["membuat bagian lain terasa lebih terang","mengurangi kesan manis","menutup detail yang halus","memperluas diffusion","menambah berat","menciptakan kekeringan","memperlambat perkembangan","atau membuat formula terasa lebih sederhana."]},{"type":"paragraph","runs":[{"text":"Pertimbangkan sebuah gagasan vanilla."}]},{"type":"paragraph","runs":[{"text":"Vanilla dapat dibuat terasa creamy ketika dipertemukan dengan lactonic effects. Ia dapat terasa lebih kering ketika ditempatkan bersama woods. Ia dapat terasa smoky ketika diberi phenolic facets, airy ketika diperluas dengan musks, boozy ketika dipasangkan dengan rum-like effects, atau lebih fruity ketika bertemu plum dan dried-fruit nuances."}]},{"type":"paragraph","runs":[{"text":"Kita masih dapat menyebut semuanya sebagai “vanilla”, tetapi pengalaman yang dihasilkan bisa sangat berbeda."}]},{"type":"paragraph","runs":[{"text":"Di sinilah perbedaan antara tema dan struktur menjadi penting."}]},{"type":"paragraph","runs":[{"text":"Tema memberi tahu kita arah umum. Struktur menentukan bagaimana arah itu benar-benar hadir."}]},{"type":"heading","level":3,"text":"Contoh dari Indische Artisan: Iron Banana"},{"type":"paragraph","runs":[{"text":"Nama"},{"text":"Iron Banana","emphasis":true},{"text":"mengandung dua gagasan yang tampak jelas: banana dan iron."}]},{"type":"paragraph","runs":[{"text":"Namun nama tersebut belum menjelaskan parfum akhirnya."}]},{"type":"paragraph","runs":[{"text":"Perfumer masih harus menentukan:"}]},{"type":"bullet_list","items":["Apakah banana terasa matang, hijau, creamy, candy-like, atau artificial?","Apakah iron terasa dingin, mineral, metallic, industrial, atau seperti darah?","Apakah banana dan iron menyatu?","Apakah keduanya saling bertabrakan?","Mana yang muncul lebih dahulu?","Apakah drydown masih mempertahankan ketegangan itu?","Apakah parfum terasa lucu, asing, agresif, atau justru nyaman?"]},{"type":"paragraph","runs":[{"text":"Keputusan-keputusan tersebut jauh lebih penting daripada sekadar memastikan bahwa “banana” dan “metallic” dapat tercium."}]},{"type":"paragraph","runs":[{"text":"Hal yang sama berlaku untuk parfum apa pun."}]},{"type":"paragraph","runs":[{"text":"Sebuah rose fragrance bukan hanya tentang kehadiran rose. Pertanyaannya adalah rose seperti apa, berada di ruang seperti apa, ditemani oleh apa, memiliki tekstur seperti apa, dan bagaimana ia berubah sepanjang waktu."}]},{"type":"heading","level":4,"text":"Kesalahpahaman umum"},{"type":"paragraph","runs":[{"text":"Semakin banyak material, semakin kompleks parfumnya.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Jumlah material tidak otomatis menentukan kedalaman sebuah parfum."}]},{"type":"paragraph","runs":[{"text":"Formula yang relatif ringkas dapat terasa kaya dan berkembang dengan baik jika hubungan antar-materialnya jelas. Sebaliknya, formula yang berisi banyak material dapat terasa penuh tetapi tidak memiliki arah."}]},{"type":"paragraph","runs":[{"text":"Kompleksitas yang berguna datang dari hubungan, bukan sekadar jumlah."}]},{"type":"heading","level":2,"text":"4. Penciptaan Terjadi Melalui Modifikasi"},{"type":"paragraph","runs":[{"text":"Dalam imajinasi populer, perfumer yang berbakat mungkin digambarkan menemukan formula final dalam satu kali percobaan."}]},{"type":"paragraph","runs":[{"text":"Dalam praktiknya, penciptaan sering berlangsung melalui modifikasi."}]},{"type":"paragraph","runs":[{"text":"Satu ide dapat menghasilkan banyak versi:"}]},{"type":"bullet_list","items":["Modification 01","Modification 02","Modification 03","Modification 04"]},{"type":"paragraph","runs":[{"text":"Perbedaan antarversi tidak selalu besar."}]},{"type":"paragraph","runs":[{"text":"Satu versi mungkin mengurangi sweetness. Versi lain mencoba meningkatkan diffusion. Modifikasi berikutnya mungkin membersihkan opening, mengurangi harshness, memberi lebih banyak ruang pada heart, atau memperpanjang drydown."}]},{"type":"paragraph","runs":[{"text":"Setiap modifikasi adalah sebuah pertanyaan."}]},{"type":"quote","runs":[{"text":"Apa yang terjadi jika bagian ini dikurangi?"}]},{"type":"quote","runs":[{"text":"Apa yang terjadi jika struktur dibuat lebih ringan?"}]},{"type":"quote","runs":[{"text":"Apakah kesan utama masih terbaca setelah tiga jam?"}]},{"type":"quote","runs":[{"text":"Apakah bagian yang menarik justru hilang ketika formula dibuat lebih halus?"}]},{"type":"paragraph","runs":[{"text":"Prosesnya dapat digambarkan sebagai lingkaran:"}]},{"type":"paragraph","runs":[{"text":"Compose","emphasis":true},{"text":"→"},{"text":"Smell","emphasis":true},{"text":"→"},{"text":"Wait","emphasis":true},{"text":"→"},{"text":"Compare","emphasis":true},{"text":"→"},{"text":"Record","emphasis":true},{"text":"→"},{"text":"Modify","emphasis":true},{"text":"→"},{"text":"Smell again","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Menunggu adalah bagian penting dari proses ini."}]},{"type":"paragraph","runs":[{"text":"Sebuah formula dapat terasa tajam pada menit pertama, lalu menjadi seimbang setelah beberapa waktu. Formula lain mungkin memiliki opening yang menarik, tetapi kehilangan arah setelah satu jam."}]},{"type":"paragraph","runs":[{"text":"Karena itu, keputusan tidak sebaiknya dibuat hanya dari kesan pertama."}]},{"type":"paragraph","runs":[{"text":"Perfumer perlu mencium pada beberapa tahap, membandingkan modifikasi pada blotter yang berbeda, dan mencatat perubahan secara konsisten."}]},{"type":"paragraph","runs":[{"text":"Catatan membantu mengurangi ketergantungan pada ingatan. Ia juga membantu perfumer melihat pola: perubahan apa yang berhasil, apa yang menghilang, dan apa yang terus menjadi masalah."}]},{"type":"heading","level":4,"text":"Perfumer’s Note"},{"type":"paragraph","runs":[{"text":"Jangan menilai terlalu cepat.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Opening sering menjadi bagian yang paling mudah menarik perhatian, tetapi bukan selalu bagian yang paling penting."}]},{"type":"paragraph","runs":[{"text":"Berikan formula waktu untuk memperlihatkan strukturnya. Beberapa masalah hanya muncul setelah bagian yang lebih cepat menguap mulai berkurang."}]},{"type":"heading","level":4,"text":"Kesalahpahaman umum"},{"type":"paragraph","runs":[{"text":"Modifikasi berarti formula sebelumnya gagal.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Tidak selalu."}]},{"type":"paragraph","runs":[{"text":"Modifikasi adalah cara untuk memahami sebuah formula. Bahkan versi yang tidak dipilih dapat menunjukkan batas, kemungkinan, dan arah yang sebelumnya tidak terlihat."}]}]}$academy_complete$::jsonb),
      (9, 'en', $academy_complete${"title":"The Evaluation Loop","steps":["Compose","Smell","Wait","Compare","Record","Modify","Smell again"]}$academy_complete$::jsonb),
      (9, 'id', $academy_complete${"title":"Siklus Evaluasi","steps":["Compose","Smell","Wait","Compare","Record","Modify","Smell again"]}$academy_complete$::jsonb),
      (10, 'en', $academy_complete${"title":"Do Not Judge Too Quickly","sections":[{"type":"paragraph","runs":[{"text":"When smelling a material, do not ask only:"}]},{"type":"quote","runs":[{"text":"What does it smell like?"}]},{"type":"paragraph","runs":[{"text":"Begin asking:"}]},{"type":"quote","runs":[{"text":"What might this material do when placed beside other materials?"}]},{"type":"paragraph","runs":[{"text":"The second question brings you closer to the way a perfumer thinks."}]}]}$academy_complete$::jsonb),
      (10, 'id', $academy_complete${"title":"Jangan Menilai Terlalu Cepat","sections":[{"type":"paragraph","runs":[{"text":"Material memiliki tugas.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Saat mencium sebuah material, jangan hanya bertanya, “Baunya seperti apa?"}]},{"type":"paragraph","runs":[{"text":"Mulailah bertanya, “Apa yang mungkin dilakukan material ini ketika ditempatkan bersama material lain?"}]},{"type":"paragraph","runs":[{"text":"Pertanyaan kedua akan membawamu lebih dekat pada cara seorang perfumer berpikir."}]}]}$academy_complete$::jsonb),
      (11, 'en', $academy_complete${"heading":"5. A Perfume Must Work in the Real World","sections":[{"type":"heading","level":2,"text":"5. A Perfume Must Work in the Real World"},{"type":"paragraph","runs":[{"text":"A formula that smells interesting on a blotter is not automatically ready to become a product."}]},{"type":"paragraph","runs":[{"text":"The perfumer must consider how the fragrance will be used."}]},{"type":"paragraph","runs":[{"text":"Will it become:"}]},{"type":"bullet_list","items":["an eau de parfum","a perfume oil","a soap","a candle","a room spray","a shampoo","or another type of product?"]},{"type":"paragraph","runs":[{"text":"The medium and product category can affect how the fragrance behaves, how its performance is evaluated, and how much of each material may be used."}]},{"type":"paragraph","runs":[{"text":"Concentration also matters."}]},{"type":"paragraph","runs":[{"text":"A formula that feels balanced at one concentration may become sharp, flat, heavy, or unclear at another."}]},{"type":"paragraph","runs":[{"text":"Beyond smell, there are other considerations:"}]},{"type":"bullet_list","items":["stability","colour changes","interaction with the product base","storage","exposure to heat and light","packaging","safety","and relevant regulation."]},{"type":"paragraph","runs":[{"text":"Some fragrance materials may be restricted, prohibited, or subject to purity requirements depending on their safety evaluation and the category of finished product."}]},{"type":"paragraph","runs":[{"text":"The same numerical limit does not apply equally to every material or every product category."}]},{"type":"paragraph","runs":[{"text":"Compliance with a fragrance standard also does not remove the responsibility of the company producing the finished product. A business must still ensure that the product is safe for its intended use and compliant with the laws of the market in which it is sold."}]},{"type":"paragraph","runs":[{"text":"Safety is not something added after creativity is complete."}]},{"type":"paragraph","runs":[{"text":"It is one of the real boundaries within which creativity operates."}]},{"type":"paragraph","runs":[{"text":"A perfumer must not only ask:"}]},{"type":"quote","runs":[{"text":"Is this interesting?"}]},{"type":"paragraph","runs":[{"text":"They must also ask:"}]},{"type":"quote","runs":[{"text":"Is this formula appropriate for its intended product and use?"}]},{"type":"heading","level":4,"text":"Common misconception"},{"type":"paragraph","runs":[{"text":"If a material is permitted, it can be used in any amount.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"It cannot."}]},{"type":"paragraph","runs":[{"text":"Some materials have restrictions, purity requirements, or prohibitions based on safety assessment and product category. Different products create different forms and levels of exposure."}]}]}$academy_complete$::jsonb),
      (11, 'id', $academy_complete${"heading":"5. Sebuah Parfum Harus Bekerja di Dunia Nyata","sections":[{"type":"heading","level":2,"text":"5. Sebuah Parfum Harus Bekerja di Dunia Nyata"},{"type":"paragraph","runs":[{"text":"Formula yang menarik pada blotter belum tentu siap menjadi produk."}]},{"type":"paragraph","runs":[{"text":"Perfumer harus mempertimbangkan konteks penggunaannya."}]},{"type":"paragraph","runs":[{"text":"Apakah fragrance tersebut akan digunakan sebagai:"}]},{"type":"bullet_list","items":["eau de parfum","perfume oil","sabun","lilin","room spray","shampoo","atau produk lain?"]},{"type":"paragraph","runs":[{"text":"Medium dan kategori produk dapat memengaruhi bagaimana fragrance berperilaku, berapa banyak material yang dapat digunakan, dan bagaimana performanya dinilai."}]},{"type":"paragraph","runs":[{"text":"Konsentrasi juga berpengaruh."}]},{"type":"paragraph","runs":[{"text":"Formula yang menarik pada konsentrasi tertentu dapat terasa terlalu tajam, terlalu datar, atau kehilangan keseimbangan ketika digunakan pada konsentrasi berbeda."}]},{"type":"paragraph","runs":[{"text":"Selain aroma, terdapat pertimbangan lain:"}]},{"type":"bullet_list","items":["stabilitas","perubahan warna","interaksi dengan medium","penyimpanan","paparan panas atau cahaya","packaging","keselamatan","serta aturan yang berlaku untuk produk tersebut."]},{"type":"paragraph","runs":[{"text":"IFRA Standards dapat melarang material tertentu, membatasi jumlah penggunaannya, atau menetapkan persyaratan seperti kemurnian. Batas penggunaan ditentukan berdasarkan material dan kategori finished consumer product, bukan melalui satu angka yang sama untuk semua produk."}]},{"type":"paragraph","runs":[{"text":"Namun mengikuti IFRA Standards saja tidak secara otomatis menyelesaikan seluruh kewajiban. Perusahaan tetap bertanggung jawab memastikan produk yang dipasarkan aman untuk penggunaan yang dimaksud dan sesuai dengan hukum serta regulasi di wilayah penjualannya."}]},{"type":"paragraph","runs":[{"text":"Keselamatan bukan bagian yang ditempelkan setelah proses kreatif selesai."}]},{"type":"paragraph","runs":[{"text":"Keselamatan merupakan salah satu batas nyata tempat kreativitas bekerja."}]},{"type":"paragraph","runs":[{"text":"Seorang perfumer tidak hanya bertanya:"}]},{"type":"quote","runs":[{"text":"Apakah ini menarik?"}]},{"type":"paragraph","runs":[{"text":"Ia juga harus bertanya:"}]},{"type":"quote","runs":[{"text":"Apakah formula ini sesuai untuk digunakan dalam produk yang dituju?"}]},{"type":"heading","level":4,"text":"Kesalahpahaman umum"},{"type":"paragraph","runs":[{"text":"Jika suatu material diperbolehkan, berarti dapat digunakan dalam jumlah berapa pun.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Tidak."}]},{"type":"paragraph","runs":[{"text":"Beberapa material memiliki batas, larangan, atau persyaratan tertentu berdasarkan penilaian keselamatan dan jenis penggunaan akhirnya. Tidak semua material memiliki aturan yang sama, dan tidak semua kategori produk memiliki tingkat paparan yang sama."}]}]}$academy_complete$::jsonb),
      (12, 'en', $academy_complete${"heading":"6. Who Creates a Perfume?","sections":[{"type":"heading","level":2,"text":"6. Who Creates a Perfume?"},{"type":"paragraph","runs":[{"text":"A fragrance is often associated with the name of a perfumer. In professional practice, however, the finished product may involve several roles."}]},{"type":"heading","level":3,"text":"The Perfumer"},{"type":"paragraph","runs":[{"text":"The perfumer develops the formula and olfactory direction."}]},{"type":"paragraph","runs":[{"text":"They select materials, structure the relationships between them, evaluate the result, and create modifications."}]},{"type":"heading","level":3,"text":"The Evaluator or Creative Fragrance Developer"},{"type":"paragraph","runs":[{"text":"An evaluator may help interpret the brief, assess modifications, and determine whether the result remains aligned with the intended product or brand."}]},{"type":"paragraph","runs":[{"text":"In some settings, the evaluator acts as a bridge between creative language, commercial needs, and the formula itself."}]},{"type":"heading","level":3,"text":"The Laboratory Team"},{"type":"paragraph","runs":[{"text":"The laboratory team weighs formulas accurately, prepares modifications, and ensures that samples are produced consistently."}]},{"type":"paragraph","runs":[{"text":"Precision matters because even a small change can affect the result."}]},{"type":"heading","level":3,"text":"The Regulatory and Safety Team"},{"type":"paragraph","runs":[{"text":"This team reviews material restrictions, documentation, application categories, safety requirements, and regulatory obligations."}]},{"type":"heading","level":3,"text":"The Brand or Creative Director"},{"type":"paragraph","runs":[{"text":"The brand defines the world, audience, positioning, story, character, and final product direction."}]},{"type":"paragraph","runs":[{"text":"Creative direction can shape the brief before the formula is made and help determine whether the result belongs within the brand’s identity."}]},{"type":"heading","level":3,"text":"The Manufacturer"},{"type":"paragraph","runs":[{"text":"The manufacturer turns the fragrance concentrate into a finished product at production scale. This involves blending, filling, consistency, quality control, and packaging."}]},{"type":"paragraph","runs":[{"text":"Within an artisan brand such as Indische Artisan, several of these functions may be performed by the same person or by a small team."}]},{"type":"paragraph","runs":[{"text":"The functions still exist."}]},{"type":"paragraph","runs":[{"text":"There is still:"}]},{"type":"bullet_list","items":["creation","evaluation","weighing","production","checking","and decision-making."]},{"type":"paragraph","runs":[{"text":"A perfume may carry one person’s vision, but the final product still requires discipline across more than one stage."}]}]}$academy_complete$::jsonb),
      (12, 'id', $academy_complete${"heading":"6. Siapa yang Menciptakan Sebuah Parfum?","sections":[{"type":"heading","level":2,"text":"6. Siapa yang Menciptakan Sebuah Parfum?"},{"type":"paragraph","runs":[{"text":"Sebuah parfum sering dikaitkan dengan nama perfumer. Namun dalam praktik industri, produk akhir dapat melibatkan beberapa peran."}]},{"type":"heading","level":3,"text":"Perfumer"},{"type":"paragraph","runs":[{"text":"Perfumer membangun formula dan mengembangkan arah olfaktori."}]},{"type":"paragraph","runs":[{"text":"Ia memilih material, menyusun hubungan di antara material tersebut, mengevaluasi hasil, dan membuat modifikasi."}]},{"type":"heading","level":3,"text":"Evaluator atau Creative Fragrance Development"},{"type":"paragraph","runs":[{"text":"Evaluator membantu membaca brief, menilai modifikasi, dan melihat apakah hasilnya masih sesuai dengan arah produk atau brand."}]},{"type":"paragraph","runs":[{"text":"Dalam beberapa konteks, evaluator menjadi jembatan antara bahasa kreatif, kebutuhan bisnis, dan formula."}]},{"type":"heading","level":3,"text":"Laboratory Team"},{"type":"paragraph","runs":[{"text":"Tim laboratorium menimbang formula dengan akurat, menyiapkan modifikasi, serta memastikan sampel dibuat secara konsisten."}]},{"type":"paragraph","runs":[{"text":"Presisi sangat penting karena perubahan kecil dapat memengaruhi hasil."}]},{"type":"heading","level":3,"text":"Regulatory and Safety Team"},{"type":"paragraph","runs":[{"text":"Tim ini membantu menilai batas penggunaan material, dokumentasi, kategori aplikasi, dan persyaratan regulasi."}]},{"type":"heading","level":3,"text":"Brand atau Creative Director"},{"type":"paragraph","runs":[{"text":"Brand menentukan dunia, audiens, positioning, cerita, karakter, dan keputusan akhir mengenai produk."}]},{"type":"paragraph","runs":[{"text":"Creative direction dapat memberi bentuk pada brief sebelum formula dibuat dan membantu menilai apakah hasilnya sesuai dengan identitas brand."}]},{"type":"heading","level":3,"text":"Manufacturer"},{"type":"paragraph","runs":[{"text":"Manufacturer mengubah fragrance concentrate menjadi finished product dalam skala produksi, dengan memperhatikan pencampuran, pengisian, konsistensi, kontrol mutu, dan packaging."}]},{"type":"paragraph","runs":[{"text":"Pada brand artisan seperti Indische Artisan, beberapa fungsi tersebut dapat dilakukan oleh orang yang sama atau oleh tim kecil."}]},{"type":"paragraph","runs":[{"text":"Namun fungsi-fungsinya tetap ada."}]},{"type":"paragraph","runs":[{"text":"Tetap ada proses:"}]},{"type":"bullet_list","items":["menciptakan","mengevaluasi","menimbang","memproduksi","memeriksa","dan mengambil keputusan."]},{"type":"paragraph","runs":[{"text":"Sebuah parfum dapat membawa visi satu orang, tetapi produk akhirnya tetap membutuhkan disiplin di lebih dari satu tahap."}]}]}$academy_complete$::jsonb),
      (13, 'en', $academy_complete${"title":"Smell the Decision, Not Only the Ingredient","sections":[{"type":"paragraph","runs":[{"text":"When smelling a material, do not ask only:"}]},{"type":"quote","runs":[{"text":"What does it smell like?"}]},{"type":"paragraph","runs":[{"text":"Begin asking:"}]},{"type":"quote","runs":[{"text":"What might this material do when placed beside other materials?"}]},{"type":"paragraph","runs":[{"text":"The second question brings you closer to the way a perfumer thinks."}]},{"type":"paragraph","runs":[{"text":"Natural materials are real, while synthetic materials are fake.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Both are real materials. Their differences relate to origin, method of production, composition, character, consistency, function, and use."}]},{"type":"paragraph","runs":[{"text":"Imagine that you have several materials that each smell interesting on their own."}]},{"type":"paragraph","runs":[{"text":"When combined, they will not necessarily produce a good perfume."}]},{"type":"paragraph","runs":[{"text":"Why?"}]},{"type":"paragraph","runs":[{"text":"Because a formula is not merely a collection of ingredients. It is a system of relationships."}]},{"type":"paragraph","runs":[{"text":"When one material is added, it does not only introduce its own smell. It can change how other materials are perceived."}]},{"type":"paragraph","runs":[{"text":"A material may:"}]},{"type":"bullet_list","items":["make another part feel brighter","reduce sweetness","cover a delicate detail","increase diffusion","add weight","create dryness","slow the development","or make the formula feel simpler."]},{"type":"paragraph","runs":[{"text":"Consider the idea of vanilla."}]},{"type":"paragraph","runs":[{"text":"Vanilla may feel creamy when combined with lactonic effects. It may become drier beside woods, smokier through phenolic facets, airier with musks, boozier beside rum-like effects, or fruitier when paired with plum and dried-fruit nuances."}]},{"type":"paragraph","runs":[{"text":"All of these fragrances may still be described as vanilla, but the experience they create can be entirely different."}]},{"type":"paragraph","runs":[{"text":"This is where the difference between theme and structure becomes important."}]},{"type":"paragraph","runs":[{"text":"A theme suggests the general direction. Structure determines how that direction is actually experienced."}]},{"type":"paragraph","runs":[{"text":"The name"},{"text":"Iron Banana","emphasis":true},{"text":"contains two seemingly clear ideas: banana and iron."}]},{"type":"paragraph","runs":[{"text":"Yet the name does not determine the final perfume."}]},{"type":"paragraph","runs":[{"text":"The perfumer must still decide:"}]},{"type":"bullet_list","items":["Is the banana ripe, green, creamy, candy-like, or artificial?","Is the iron cold, mineral, metallic, industrial, or blood-like?","Do banana and iron blend together?","Do they remain in conflict?","Which appears first?","Does the tension remain in the drydown?","Does the fragrance feel humorous, strange, aggressive, or unexpectedly comforting?"]},{"type":"paragraph","runs":[{"text":"These decisions matter more than simply ensuring that “banana” and “metal” can both be smelled."}]},{"type":"paragraph","runs":[{"text":"The same principle applies to any perfume."}]},{"type":"paragraph","runs":[{"text":"A rose fragrance is not defined only by the presence of rose. The important questions are what kind of rose it is, what surrounds it, what texture it has, where it appears to exist, and how it changes over time."}]},{"type":"paragraph","runs":[{"text":"The more materials a formula contains, the more complex it becomes.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"The number of materials does not automatically determine depth."}]},{"type":"paragraph","runs":[{"text":"A relatively concise formula may feel rich and evolving when the relationships between its materials are clear. A formula with many materials may feel crowded yet directionless."}]},{"type":"paragraph","runs":[{"text":"Useful complexity comes from relationships, not quantity alone."}]},{"type":"paragraph","runs":[{"text":"In popular imagination, a gifted perfumer may appear to discover the final formula in a single attempt."}]},{"type":"paragraph","runs":[{"text":"In practice, creation often develops through modification."}]},{"type":"paragraph","runs":[{"text":"One idea may produce many versions:"}]},{"type":"bullet_list","items":["Modification 01","Modification 02","Modification 03","Modification 04"]},{"type":"paragraph","runs":[{"text":"The differences between them may be small."}]},{"type":"paragraph","runs":[{"text":"One version may reduce sweetness. Another may attempt to increase diffusion. A later modification may clean the opening, soften harshness, give more space to the heart, or extend the drydown."}]},{"type":"paragraph","runs":[{"text":"Each modification asks a question."}]},{"type":"quote","runs":[{"text":"What happens if this part is reduced?"}]},{"type":"quote","runs":[{"text":"What happens if the structure is made lighter?"}]},{"type":"quote","runs":[{"text":"Is the central idea still clear after three hours?"}]},{"type":"quote","runs":[{"text":"Does the most interesting part disappear when the formula becomes smoother?"}]},{"type":"paragraph","runs":[{"text":"The process can be represented as a cycle:"}]},{"type":"paragraph","runs":[{"text":"Compose","emphasis":true},{"text":"→"},{"text":"Smell","emphasis":true},{"text":"→"},{"text":"Wait","emphasis":true},{"text":"→"},{"text":"Compare","emphasis":true},{"text":"→"},{"text":"Record","emphasis":true},{"text":"→"},{"text":"Modify","emphasis":true},{"text":"→"},{"text":"Smell again","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Waiting is an essential part of this process."}]},{"type":"paragraph","runs":[{"text":"A formula may feel sharp during the first few minutes and become balanced later. Another may have a compelling opening but lose direction after an hour."}]},{"type":"paragraph","runs":[{"text":"Decisions should therefore not be based only on first impressions."}]},{"type":"paragraph","runs":[{"text":"A perfumer smells at several stages, compares modifications on separate blotters, and records observations consistently."}]},{"type":"paragraph","runs":[{"text":"Notes reduce dependence on memory. They also help reveal patterns: which changes worked, what disappeared, and what continues to create problems."}]},{"type":"paragraph","runs":[{"text":"The opening is often the easiest part to notice, but it is not always the most important."}]},{"type":"paragraph","runs":[{"text":"Give the formula time to reveal its structure. Some problems only become visible after the most volatile materials begin to fade."}]},{"type":"paragraph","runs":[{"text":"Modification means that the previous formula failed.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Not necessarily."}]},{"type":"paragraph","runs":[{"text":"Modification is a method of understanding a formula. Even a version that is never selected can reveal boundaries, possibilities, and directions that were previously hidden."}]},{"type":"paragraph","runs":[{"text":"A formula that smells interesting on a blotter is not automatically ready to become a product."}]},{"type":"paragraph","runs":[{"text":"The perfumer must consider how the fragrance will be used."}]},{"type":"paragraph","runs":[{"text":"Will it become:"}]},{"type":"bullet_list","items":["an eau de parfum","a perfume oil","a soap","a candle","a room spray","a shampoo","or another type of product?"]},{"type":"paragraph","runs":[{"text":"The medium and product category can affect how the fragrance behaves, how its performance is evaluated, and how much of each material may be used."}]},{"type":"paragraph","runs":[{"text":"Concentration also matters."}]},{"type":"paragraph","runs":[{"text":"A formula that feels balanced at one concentration may become sharp, flat, heavy, or unclear at another."}]},{"type":"paragraph","runs":[{"text":"Beyond smell, there are other considerations:"}]},{"type":"bullet_list","items":["stability","colour changes","interaction with the product base","storage","exposure to heat and light","packaging","safety","and relevant regulation."]},{"type":"paragraph","runs":[{"text":"Some fragrance materials may be restricted, prohibited, or subject to purity requirements depending on their safety evaluation and the category of finished product."}]},{"type":"paragraph","runs":[{"text":"The same numerical limit does not apply equally to every material or every product category."}]},{"type":"paragraph","runs":[{"text":"Compliance with a fragrance standard also does not remove the responsibility of the company producing the finished product. A business must still ensure that the product is safe for its intended use and compliant with the laws of the market in which it is sold."}]},{"type":"paragraph","runs":[{"text":"Safety is not something added after creativity is complete."}]},{"type":"paragraph","runs":[{"text":"It is one of the real boundaries within which creativity operates."}]},{"type":"paragraph","runs":[{"text":"A perfumer must not only ask:"}]},{"type":"quote","runs":[{"text":"Is this interesting?"}]},{"type":"paragraph","runs":[{"text":"They must also ask:"}]},{"type":"quote","runs":[{"text":"Is this formula appropriate for its intended product and use?"}]},{"type":"paragraph","runs":[{"text":"If a material is permitted, it can be used in any amount.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"It cannot."}]},{"type":"paragraph","runs":[{"text":"Some materials have restrictions, purity requirements, or prohibitions based on safety assessment and product category. Different products create different forms and levels of exposure."}]},{"type":"paragraph","runs":[{"text":"A fragrance is often associated with the name of a perfumer. In professional practice, however, the finished product may involve several roles."}]},{"type":"paragraph","runs":[{"text":"The perfumer develops the formula and olfactory direction."}]},{"type":"paragraph","runs":[{"text":"They select materials, structure the relationships between them, evaluate the result, and create modifications."}]},{"type":"paragraph","runs":[{"text":"An evaluator may help interpret the brief, assess modifications, and determine whether the result remains aligned with the intended product or brand."}]},{"type":"paragraph","runs":[{"text":"In some settings, the evaluator acts as a bridge between creative language, commercial needs, and the formula itself."}]},{"type":"paragraph","runs":[{"text":"The laboratory team weighs formulas accurately, prepares modifications, and ensures that samples are produced consistently."}]},{"type":"paragraph","runs":[{"text":"Precision matters because even a small change can affect the result."}]},{"type":"paragraph","runs":[{"text":"This team reviews material restrictions, documentation, application categories, safety requirements, and regulatory obligations."}]},{"type":"paragraph","runs":[{"text":"The brand defines the world, audience, positioning, story, character, and final product direction."}]},{"type":"paragraph","runs":[{"text":"Creative direction can shape the brief before the formula is made and help determine whether the result belongs within the brand’s identity."}]},{"type":"paragraph","runs":[{"text":"The manufacturer turns the fragrance concentrate into a finished product at production scale. This involves blending, filling, consistency, quality control, and packaging."}]},{"type":"paragraph","runs":[{"text":"Within an artisan brand such as Indische Artisan, several of these functions may be performed by the same person or by a small team."}]},{"type":"paragraph","runs":[{"text":"The functions still exist."}]},{"type":"paragraph","runs":[{"text":"There is still:"}]},{"type":"bullet_list","items":["creation","evaluation","weighing","production","checking","and decision-making."]},{"type":"paragraph","runs":[{"text":"A perfume may carry one person’s vision, but the final product still requires discipline across more than one stage."}]},{"type":"paragraph","runs":[{"text":"Beginners often feel that smelling perfume means guessing ingredients."}]},{"type":"paragraph","runs":[{"text":"Is this rose?"}]},{"type":"paragraph","runs":[{"text":"Is there vanilla?"}]},{"type":"paragraph","runs":[{"text":"Could this be sandalwood?"}]},{"type":"paragraph","runs":[{"text":"The ability to identify materials is useful. It is not the only way to understand a fragrance."}]},{"type":"paragraph","runs":[{"text":"Even before you have a large material vocabulary, you can observe the decisions within a perfume."}]},{"type":"paragraph","runs":[{"text":"Ask:"}]},{"type":"bullet_list","items":["What has been made brighter?","What has been softened?","What feels distant?","What remains close to the skin?","What has been designed to last?","What has been made intentionally rough?","Are any parts in conflict?","Does the perfume move, or does it remain stable?"]},{"type":"paragraph","runs":[{"text":"When you begin to smell decisions, a fragrance no longer feels like a note-list puzzle. It begins to reveal itself as something constructed."}]}]}$academy_complete$::jsonb),
      (13, 'id', $academy_complete${"title":"Cium Keputusannya, Bukan Hanya Bahannya","sections":[{"type":"paragraph","runs":[{"text":"Material memiliki tugas.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Saat mencium sebuah material, jangan hanya bertanya, “Baunya seperti apa?"}]},{"type":"paragraph","runs":[{"text":"Mulailah bertanya, “Apa yang mungkin dilakukan material ini ketika ditempatkan bersama material lain?"}]},{"type":"paragraph","runs":[{"text":"Pertanyaan kedua akan membawamu lebih dekat pada cara seorang perfumer berpikir."}]},{"type":"paragraph","runs":[{"text":"Natural adalah bahan asli, sedangkan synthetic adalah bahan palsu.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Keduanya merupakan material nyata. Perbedaannya berkaitan dengan asal, cara produksi, komposisi, karakter, konsistensi, fungsi, serta cara penggunaannya."}]},{"type":"paragraph","runs":[{"text":"Bayangkan kamu memiliki beberapa material yang masing-masing terasa menarik ketika dicium sendiri."}]},{"type":"paragraph","runs":[{"text":"Ketika material-material tersebut dicampurkan, hasilnya belum tentu menjadi parfum yang baik."}]},{"type":"paragraph","runs":[{"text":"Mengapa?"}]},{"type":"paragraph","runs":[{"text":"Karena formula bukan sekadar kumpulan bahan. Formula adalah sistem hubungan."}]},{"type":"paragraph","runs":[{"text":"Ketika satu material ditambahkan, ia tidak hanya membawa aromanya sendiri. Ia dapat mengubah cara material lain dirasakan."}]},{"type":"paragraph","runs":[{"text":"Sebuah material dapat:"}]},{"type":"bullet_list","items":["membuat bagian lain terasa lebih terang","mengurangi kesan manis","menutup detail yang halus","memperluas diffusion","menambah berat","menciptakan kekeringan","memperlambat perkembangan","atau membuat formula terasa lebih sederhana."]},{"type":"paragraph","runs":[{"text":"Pertimbangkan sebuah gagasan vanilla."}]},{"type":"paragraph","runs":[{"text":"Vanilla dapat dibuat terasa creamy ketika dipertemukan dengan lactonic effects. Ia dapat terasa lebih kering ketika ditempatkan bersama woods. Ia dapat terasa smoky ketika diberi phenolic facets, airy ketika diperluas dengan musks, boozy ketika dipasangkan dengan rum-like effects, atau lebih fruity ketika bertemu plum dan dried-fruit nuances."}]},{"type":"paragraph","runs":[{"text":"Kita masih dapat menyebut semuanya sebagai “vanilla”, tetapi pengalaman yang dihasilkan bisa sangat berbeda."}]},{"type":"paragraph","runs":[{"text":"Di sinilah perbedaan antara tema dan struktur menjadi penting."}]},{"type":"paragraph","runs":[{"text":"Tema memberi tahu kita arah umum. Struktur menentukan bagaimana arah itu benar-benar hadir."}]},{"type":"paragraph","runs":[{"text":"Nama"},{"text":"Iron Banana","emphasis":true},{"text":"mengandung dua gagasan yang tampak jelas: banana dan iron."}]},{"type":"paragraph","runs":[{"text":"Namun nama tersebut belum menjelaskan parfum akhirnya."}]},{"type":"paragraph","runs":[{"text":"Perfumer masih harus menentukan:"}]},{"type":"bullet_list","items":["Apakah banana terasa matang, hijau, creamy, candy-like, atau artificial?","Apakah iron terasa dingin, mineral, metallic, industrial, atau seperti darah?","Apakah banana dan iron menyatu?","Apakah keduanya saling bertabrakan?","Mana yang muncul lebih dahulu?","Apakah drydown masih mempertahankan ketegangan itu?","Apakah parfum terasa lucu, asing, agresif, atau justru nyaman?"]},{"type":"paragraph","runs":[{"text":"Keputusan-keputusan tersebut jauh lebih penting daripada sekadar memastikan bahwa “banana” dan “metallic” dapat tercium."}]},{"type":"paragraph","runs":[{"text":"Hal yang sama berlaku untuk parfum apa pun."}]},{"type":"paragraph","runs":[{"text":"Sebuah rose fragrance bukan hanya tentang kehadiran rose. Pertanyaannya adalah rose seperti apa, berada di ruang seperti apa, ditemani oleh apa, memiliki tekstur seperti apa, dan bagaimana ia berubah sepanjang waktu."}]},{"type":"paragraph","runs":[{"text":"Semakin banyak material, semakin kompleks parfumnya.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Jumlah material tidak otomatis menentukan kedalaman sebuah parfum."}]},{"type":"paragraph","runs":[{"text":"Formula yang relatif ringkas dapat terasa kaya dan berkembang dengan baik jika hubungan antar-materialnya jelas. Sebaliknya, formula yang berisi banyak material dapat terasa penuh tetapi tidak memiliki arah."}]},{"type":"paragraph","runs":[{"text":"Kompleksitas yang berguna datang dari hubungan, bukan sekadar jumlah."}]},{"type":"paragraph","runs":[{"text":"Dalam imajinasi populer, perfumer yang berbakat mungkin digambarkan menemukan formula final dalam satu kali percobaan."}]},{"type":"paragraph","runs":[{"text":"Dalam praktiknya, penciptaan sering berlangsung melalui modifikasi."}]},{"type":"paragraph","runs":[{"text":"Satu ide dapat menghasilkan banyak versi:"}]},{"type":"bullet_list","items":["Modification 01","Modification 02","Modification 03","Modification 04"]},{"type":"paragraph","runs":[{"text":"Perbedaan antarversi tidak selalu besar."}]},{"type":"paragraph","runs":[{"text":"Satu versi mungkin mengurangi sweetness. Versi lain mencoba meningkatkan diffusion. Modifikasi berikutnya mungkin membersihkan opening, mengurangi harshness, memberi lebih banyak ruang pada heart, atau memperpanjang drydown."}]},{"type":"paragraph","runs":[{"text":"Setiap modifikasi adalah sebuah pertanyaan."}]},{"type":"quote","runs":[{"text":"Apa yang terjadi jika bagian ini dikurangi?"}]},{"type":"quote","runs":[{"text":"Apa yang terjadi jika struktur dibuat lebih ringan?"}]},{"type":"quote","runs":[{"text":"Apakah kesan utama masih terbaca setelah tiga jam?"}]},{"type":"quote","runs":[{"text":"Apakah bagian yang menarik justru hilang ketika formula dibuat lebih halus?"}]},{"type":"paragraph","runs":[{"text":"Prosesnya dapat digambarkan sebagai lingkaran:"}]},{"type":"paragraph","runs":[{"text":"Compose","emphasis":true},{"text":"→"},{"text":"Smell","emphasis":true},{"text":"→"},{"text":"Wait","emphasis":true},{"text":"→"},{"text":"Compare","emphasis":true},{"text":"→"},{"text":"Record","emphasis":true},{"text":"→"},{"text":"Modify","emphasis":true},{"text":"→"},{"text":"Smell again","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Menunggu adalah bagian penting dari proses ini."}]},{"type":"paragraph","runs":[{"text":"Sebuah formula dapat terasa tajam pada menit pertama, lalu menjadi seimbang setelah beberapa waktu. Formula lain mungkin memiliki opening yang menarik, tetapi kehilangan arah setelah satu jam."}]},{"type":"paragraph","runs":[{"text":"Karena itu, keputusan tidak sebaiknya dibuat hanya dari kesan pertama."}]},{"type":"paragraph","runs":[{"text":"Perfumer perlu mencium pada beberapa tahap, membandingkan modifikasi pada blotter yang berbeda, dan mencatat perubahan secara konsisten."}]},{"type":"paragraph","runs":[{"text":"Catatan membantu mengurangi ketergantungan pada ingatan. Ia juga membantu perfumer melihat pola: perubahan apa yang berhasil, apa yang menghilang, dan apa yang terus menjadi masalah."}]},{"type":"paragraph","runs":[{"text":"Jangan menilai terlalu cepat.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Opening sering menjadi bagian yang paling mudah menarik perhatian, tetapi bukan selalu bagian yang paling penting."}]},{"type":"paragraph","runs":[{"text":"Berikan formula waktu untuk memperlihatkan strukturnya. Beberapa masalah hanya muncul setelah bagian yang lebih cepat menguap mulai berkurang."}]},{"type":"paragraph","runs":[{"text":"Modifikasi berarti formula sebelumnya gagal.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Tidak selalu."}]},{"type":"paragraph","runs":[{"text":"Modifikasi adalah cara untuk memahami sebuah formula. Bahkan versi yang tidak dipilih dapat menunjukkan batas, kemungkinan, dan arah yang sebelumnya tidak terlihat."}]},{"type":"paragraph","runs":[{"text":"Formula yang menarik pada blotter belum tentu siap menjadi produk."}]},{"type":"paragraph","runs":[{"text":"Perfumer harus mempertimbangkan konteks penggunaannya."}]},{"type":"paragraph","runs":[{"text":"Apakah fragrance tersebut akan digunakan sebagai:"}]},{"type":"bullet_list","items":["eau de parfum","perfume oil","sabun","lilin","room spray","shampoo","atau produk lain?"]},{"type":"paragraph","runs":[{"text":"Medium dan kategori produk dapat memengaruhi bagaimana fragrance berperilaku, berapa banyak material yang dapat digunakan, dan bagaimana performanya dinilai."}]},{"type":"paragraph","runs":[{"text":"Konsentrasi juga berpengaruh."}]},{"type":"paragraph","runs":[{"text":"Formula yang menarik pada konsentrasi tertentu dapat terasa terlalu tajam, terlalu datar, atau kehilangan keseimbangan ketika digunakan pada konsentrasi berbeda."}]},{"type":"paragraph","runs":[{"text":"Selain aroma, terdapat pertimbangan lain:"}]},{"type":"bullet_list","items":["stabilitas","perubahan warna","interaksi dengan medium","penyimpanan","paparan panas atau cahaya","packaging","keselamatan","serta aturan yang berlaku untuk produk tersebut."]},{"type":"paragraph","runs":[{"text":"IFRA Standards dapat melarang material tertentu, membatasi jumlah penggunaannya, atau menetapkan persyaratan seperti kemurnian. Batas penggunaan ditentukan berdasarkan material dan kategori finished consumer product, bukan melalui satu angka yang sama untuk semua produk."}]},{"type":"paragraph","runs":[{"text":"Namun mengikuti IFRA Standards saja tidak secara otomatis menyelesaikan seluruh kewajiban. Perusahaan tetap bertanggung jawab memastikan produk yang dipasarkan aman untuk penggunaan yang dimaksud dan sesuai dengan hukum serta regulasi di wilayah penjualannya."}]},{"type":"paragraph","runs":[{"text":"Keselamatan bukan bagian yang ditempelkan setelah proses kreatif selesai."}]},{"type":"paragraph","runs":[{"text":"Keselamatan merupakan salah satu batas nyata tempat kreativitas bekerja."}]},{"type":"paragraph","runs":[{"text":"Seorang perfumer tidak hanya bertanya:"}]},{"type":"quote","runs":[{"text":"Apakah ini menarik?"}]},{"type":"paragraph","runs":[{"text":"Ia juga harus bertanya:"}]},{"type":"quote","runs":[{"text":"Apakah formula ini sesuai untuk digunakan dalam produk yang dituju?"}]},{"type":"paragraph","runs":[{"text":"Jika suatu material diperbolehkan, berarti dapat digunakan dalam jumlah berapa pun.","emphasis":true}]},{"type":"paragraph","runs":[{"text":"Tidak."}]},{"type":"paragraph","runs":[{"text":"Beberapa material memiliki batas, larangan, atau persyaratan tertentu berdasarkan penilaian keselamatan dan jenis penggunaan akhirnya. Tidak semua material memiliki aturan yang sama, dan tidak semua kategori produk memiliki tingkat paparan yang sama."}]},{"type":"paragraph","runs":[{"text":"Sebuah parfum sering dikaitkan dengan nama perfumer. Namun dalam praktik industri, produk akhir dapat melibatkan beberapa peran."}]},{"type":"paragraph","runs":[{"text":"Perfumer membangun formula dan mengembangkan arah olfaktori."}]},{"type":"paragraph","runs":[{"text":"Ia memilih material, menyusun hubungan di antara material tersebut, mengevaluasi hasil, dan membuat modifikasi."}]},{"type":"paragraph","runs":[{"text":"Evaluator membantu membaca brief, menilai modifikasi, dan melihat apakah hasilnya masih sesuai dengan arah produk atau brand."}]},{"type":"paragraph","runs":[{"text":"Dalam beberapa konteks, evaluator menjadi jembatan antara bahasa kreatif, kebutuhan bisnis, dan formula."}]},{"type":"paragraph","runs":[{"text":"Tim laboratorium menimbang formula dengan akurat, menyiapkan modifikasi, serta memastikan sampel dibuat secara konsisten."}]},{"type":"paragraph","runs":[{"text":"Presisi sangat penting karena perubahan kecil dapat memengaruhi hasil."}]},{"type":"paragraph","runs":[{"text":"Tim ini membantu menilai batas penggunaan material, dokumentasi, kategori aplikasi, dan persyaratan regulasi."}]},{"type":"paragraph","runs":[{"text":"Brand menentukan dunia, audiens, positioning, cerita, karakter, dan keputusan akhir mengenai produk."}]},{"type":"paragraph","runs":[{"text":"Creative direction dapat memberi bentuk pada brief sebelum formula dibuat dan membantu menilai apakah hasilnya sesuai dengan identitas brand."}]},{"type":"paragraph","runs":[{"text":"Manufacturer mengubah fragrance concentrate menjadi finished product dalam skala produksi, dengan memperhatikan pencampuran, pengisian, konsistensi, kontrol mutu, dan packaging."}]},{"type":"paragraph","runs":[{"text":"Pada brand artisan seperti Indische Artisan, beberapa fungsi tersebut dapat dilakukan oleh orang yang sama atau oleh tim kecil."}]},{"type":"paragraph","runs":[{"text":"Namun fungsi-fungsinya tetap ada."}]},{"type":"paragraph","runs":[{"text":"Tetap ada proses:"}]},{"type":"bullet_list","items":["menciptakan","mengevaluasi","menimbang","memproduksi","memeriksa","dan mengambil keputusan."]},{"type":"paragraph","runs":[{"text":"Sebuah parfum dapat membawa visi satu orang, tetapi produk akhirnya tetap membutuhkan disiplin di lebih dari satu tahap."}]},{"type":"paragraph","runs":[{"text":"Pemula sering merasa bahwa mencium parfum berarti menebak bahan."}]},{"type":"paragraph","runs":[{"text":"Apakah ini rose?"}]},{"type":"paragraph","runs":[{"text":"Apakah ada vanilla?"}]},{"type":"paragraph","runs":[{"text":"Apakah ini sandalwood?"}]},{"type":"paragraph","runs":[{"text":"Kemampuan mengenali material memang berguna. Namun itu bukan satu-satunya cara memahami parfum."}]},{"type":"paragraph","runs":[{"text":"Sebelum memiliki vocabulary material yang luas, kamu tetap dapat mengamati keputusan di dalamnya."}]},{"type":"paragraph","runs":[{"text":"Tanyakan:"}]},{"type":"bullet_list","items":["Apa yang dibuat terasa terang?","Apa yang dibuat terasa lembut?","Apa yang dibuat terasa jauh?","Apa yang dibuat dekat dengan kulit?","Apa yang dibuat bertahan?","Apa yang sengaja dibuat kasar?","Apakah ada bagian yang bertabrakan?","Apakah parfum ini bergerak atau tetap stabil?"]},{"type":"paragraph","runs":[{"text":"Ketika kamu mulai mencium keputusan, parfum tidak lagi terasa seperti teka-teki note list. Ia mulai terlihat sebagai sesuatu yang dibangun."}]}]}$academy_complete$::jsonb),
      (14, 'en', $academy_complete${"title":"Reading a Perfume Without Reading Its Notes","sections":[{"type":"heading","level":3,"text":"Purpose"},{"type":"paragraph","runs":[{"text":"This exercise helps you observe a fragrance as the result of creative decisions before reading the brand’s official description."}]},{"type":"heading","level":3,"text":"What You Need"},{"type":"bullet_list","items":["one perfume you already own","a blotter or unscented piece of paper","a notebook","a timer."]},{"type":"heading","level":3,"text":"Step 1 — Hide the Note List"},{"type":"paragraph","runs":[{"text":"Do not read the note list, product description, reviews, or other people’s impressions."}]},{"type":"paragraph","runs":[{"text":"If you have seen them before, try to set that information aside during the exercise."}]},{"type":"heading","level":3,"text":"Step 2 — Smell the Opening"},{"type":"paragraph","runs":[{"text":"Spray the perfume once onto the blotter."}]},{"type":"paragraph","runs":[{"text":"Wait a few seconds, then smell without placing it too close to your nose."}]},{"type":"paragraph","runs":[{"text":"Write down three first impressions."}]},{"type":"paragraph","runs":[{"text":"Then choose words for the following dimensions:"}]},{"type":"bullet_list","items":["bright or dark","warm or cool","light or heavy","close or expansive","familiar or strange","smooth or textured."]},{"type":"paragraph","runs":[{"text":"You do not need to identify any notes."}]},{"type":"heading","level":3,"text":"Step 3 — Imagine the Intention"},{"type":"paragraph","runs":[{"text":"Ask:"}]},{"type":"bullet_list","items":["When does this perfume feel appropriate to wear?","What kind of space belongs to it?","What kind of person might wear it?","Does it seem designed to comfort, refresh, attract attention, create distance, or cause slight unease?","Does one idea appear stronger than the others?"]},{"type":"paragraph","runs":[{"text":"There is no official answer."}]},{"type":"paragraph","runs":[{"text":"The purpose is to observe direction, not to discover a single truth."}]},{"type":"heading","level":3,"text":"Step 4 — Wait"},{"type":"paragraph","runs":[{"text":"Set the blotter aside."}]},{"type":"paragraph","runs":[{"text":"Smell it again after 15–20 minutes."}]},{"type":"paragraph","runs":[{"text":"Record:"}]},{"type":"bullet_list","items":["what has softened","what has become clearer","what has diminished","whether the texture has changed","whether the scent feels closer or more expansive","whether your initial interpretation still feels accurate."]},{"type":"heading","level":3,"text":"Step 5 — Read the Brand Description"},{"type":"paragraph","runs":[{"text":"Now read the official note list and product description."}]},{"type":"paragraph","runs":[{"text":"Compare them with your observations."}]},{"type":"paragraph","runs":[{"text":"Write down:"}]},{"type":"bullet_list","items":["what matched","what was listed but you did not perceive","what you perceived but was not listed","whether the description changed the way you smelled the perfume."]},{"type":"heading","level":3,"text":"Remember"},{"type":"paragraph","runs":[{"text":"A note list is a communication tool."}]},{"type":"paragraph","runs":[{"text":"It can help a brand describe a fragrance, but it is not a complete formula and should not always be read as a literal list of every material used."}]},{"type":"paragraph","runs":[{"text":"Your direct experience of smelling remains the primary source of observation."}]}]}$academy_complete$::jsonb),
      (14, 'id', $academy_complete${"title":"Membaca Parfum Tanpa Membaca Notes-nya","sections":[{"type":"heading","level":3,"text":"Tujuan"},{"type":"paragraph","runs":[{"text":"Latihan ini membantumu mengamati sebuah parfum sebagai hasil keputusan kreatif sebelum melihat deskripsi resmi brand."}]},{"type":"heading","level":3,"text":"Yang Dibutuhkan"},{"type":"bullet_list","items":["satu parfum yang sudah kamu miliki","blotter atau kertas yang tidak beraroma","buku catatan","timer."]},{"type":"heading","level":3,"text":"Langkah 1 — Sembunyikan Note List"},{"type":"paragraph","runs":[{"text":"Jangan membaca note list, review, deskripsi produk, atau komentar orang lain."}]},{"type":"paragraph","runs":[{"text":"Bila kamu sudah pernah membacanya, coba sisihkan informasi tersebut selama latihan."}]},{"type":"heading","level":3,"text":"Langkah 2 — Cium Opening"},{"type":"paragraph","runs":[{"text":"Semprotkan parfum satu kali pada blotter."}]},{"type":"paragraph","runs":[{"text":"Tunggu beberapa detik, lalu cium tanpa menempelkan blotter terlalu dekat ke hidung."}]},{"type":"paragraph","runs":[{"text":"Tuliskan tiga kesan pertama."}]},{"type":"paragraph","runs":[{"text":"Setelah itu, pilih kata untuk beberapa dimensi berikut:"}]},{"type":"bullet_list","items":["terang atau gelap","hangat atau dingin","ringan atau berat","dekat atau luas","familiar atau asing","halus atau bertekstur."]},{"type":"paragraph","runs":[{"text":"Tidak perlu menebak notes."}]},{"type":"heading","level":3,"text":"Langkah 3 — Bayangkan Maksudnya"},{"type":"paragraph","runs":[{"text":"Tanyakan:"}]},{"type":"bullet_list","items":["Kapan parfum ini terasa cocok digunakan?","Ruang seperti apa yang sesuai dengannya?","Karakter seperti apa yang mungkin memakainya?","Apakah parfum ini ingin menenangkan, menyegarkan, menarik perhatian, menjaga jarak, atau menciptakan rasa tidak nyaman?","Apakah ada satu gagasan yang terasa lebih kuat daripada yang lain?"]},{"type":"paragraph","runs":[{"text":"Tidak ada jawaban resmi untuk bagian ini."}]},{"type":"paragraph","runs":[{"text":"Tujuannya adalah memperhatikan arah, bukan mencari kebenaran tunggal."}]},{"type":"heading","level":3,"text":"Langkah 4 — Tunggu"},{"type":"paragraph","runs":[{"text":"Letakkan blotter."}]},{"type":"paragraph","runs":[{"text":"Cium kembali setelah 15–20 menit."}]},{"type":"paragraph","runs":[{"text":"Catat:"}]},{"type":"bullet_list","items":["apa yang melembut","apa yang menjadi lebih jelas","apa yang berkurang","apakah teksturnya berubah","apakah ruangnya terasa lebih dekat atau luas","apakah gagasan pertamamu masih sama."]},{"type":"heading","level":3,"text":"Langkah 5 — Baca Deskripsi Brand"},{"type":"paragraph","runs":[{"text":"Sekarang lihat note list dan deskripsi resmi parfum tersebut."}]},{"type":"paragraph","runs":[{"text":"Bandingkan dengan pengamatanmu."}]},{"type":"paragraph","runs":[{"text":"Tuliskan:"}]},{"type":"bullet_list","items":["hal yang sesuai","hal yang disebutkan tetapi tidak kamu rasakan","hal yang kamu rasakan tetapi tidak disebutkan","apakah deskripsi brand mengubah cara kamu mencium parfum tersebut."]},{"type":"heading","level":3,"text":"Hal yang Perlu Diingat"},{"type":"paragraph","runs":[{"text":"Note list adalah alat komunikasi."}]},{"type":"paragraph","runs":[{"text":"Ia dapat membantu brand memberi gambaran tentang sebuah parfum, tetapi ia bukan formula lengkap dan tidak selalu merupakan daftar literal dari setiap material yang digunakan."}]},{"type":"paragraph","runs":[{"text":"Pengalaman mencium tetap menjadi sumber utama pengamatanmu."}]}]}$academy_complete$::jsonb),
      (15, 'en', $academy_complete${"title":"Reflection","sections":[{"type":"paragraph","runs":[{"text":"Answer these questions in a notebook or personal notes app."}]},{"type":"numbered_list","items":["Before this lesson, what did you imagine a perfumer actually did?","Did the perfume you observed seem to have one clear intention?","Which decision was most noticeable: texture, strength, contrast, space, or development?","Did reading the note list change your perception?","What is one thing you want to observe the next time you smell a perfume?"]}]}$academy_complete$::jsonb),
      (15, 'id', $academy_complete${"title":"Refleksi","sections":[{"type":"paragraph","runs":[{"text":"Jawab di buku catatan atau aplikasi catatan pribadi."}]},{"type":"numbered_list","items":["Sebelum lesson ini, apa yang kamu bayangkan dilakukan seorang perfumer?","Apakah parfum yang kamu amati terasa memiliki satu maksud yang jelas?","Keputusan apa yang paling terasa: texture, strength, contrast, space, atau development?","Apakah membaca note list setelah mencium mengubah persepsimu?","Apa satu hal yang ingin kamu perhatikan saat mencium parfum berikutnya?"]}]}$academy_complete$::jsonb),
      (16, 'en', $academy_complete${"title":"Summary","sections":[{"type":"heading","level":3,"text":"Five Ideas to Remember"},{"type":"heading","level":4,"text":"1. Perfumery begins with intention"},{"type":"paragraph","runs":[{"text":"An idea must be translated into an olfactory direction, materials, structure, and development."}]},{"type":"heading","level":4,"text":"2. Materials have functions"},{"type":"paragraph","runs":[{"text":"Materials are not selected only for their smell. They are also chosen for what they do inside a formula."}]},{"type":"heading","level":4,"text":"3. A formula is a relationship"},{"type":"paragraph","runs":[{"text":"One material can change how another is perceived. The number of materials does not automatically determine complexity."}]},{"type":"heading","level":4,"text":"4. Evaluation is part of creation"},{"type":"paragraph","runs":[{"text":"A perfumer smells, waits, compares, records, and modifies. A final formula rarely appears through one decision."}]},{"type":"heading","level":4,"text":"5. A perfume must work as a real product"},{"type":"paragraph","runs":[{"text":"A fragrance must consider concentration, medium, performance, stability, safety, and intended use."}]}]}$academy_complete$::jsonb),
      (16, 'id', $academy_complete${"title":"Ringkasan","sections":[{"type":"heading","level":3,"text":"Lima Hal yang Perlu Diingat"},{"type":"heading","level":4,"text":"1. Perfumery dimulai dari sebuah maksud"},{"type":"paragraph","runs":[{"text":"Sebuah ide harus diterjemahkan menjadi arah olfaktori, material, struktur, dan perkembangan."}]},{"type":"heading","level":4,"text":"2. Material memiliki fungsi"},{"type":"paragraph","runs":[{"text":"Material tidak hanya dipilih karena aromanya. Ia juga dipilih berdasarkan apa yang dilakukannya di dalam formula."}]},{"type":"heading","level":4,"text":"3. Formula adalah hubungan"},{"type":"paragraph","runs":[{"text":"Satu material dapat mengubah cara material lain dirasakan. Jumlah bahan tidak otomatis menentukan kompleksitas."}]},{"type":"heading","level":4,"text":"4. Evaluasi adalah bagian dari penciptaan"},{"type":"paragraph","runs":[{"text":"Perfumer mencium, menunggu, membandingkan, mencatat, dan memodifikasi. Formula final jarang lahir dari satu keputusan."}]},{"type":"heading","level":4,"text":"5. Parfum harus bekerja sebagai produk nyata"},{"type":"paragraph","runs":[{"text":"Sebuah fragrance harus mempertimbangkan konsentrasi, medium, performa, stabilitas, keselamatan, dan penggunaan akhirnya."}]}]}$academy_complete$::jsonb),
      (17, 'en', $academy_complete${"heading":"Continue Observing","sections":[{"type":"paragraph","runs":[{"text":"Before moving to Lesson 2, choose another perfume."}]},{"type":"paragraph","runs":[{"text":"Do not look at its notes."}]},{"type":"paragraph","runs":[{"text":"Write down only five qualities:"}]},{"type":"bullet_list","items":["temperature","texture","weight","space","movement."]},{"type":"paragraph","runs":[{"text":"Keep this observation."}]},{"type":"paragraph","runs":[{"text":"In the next lesson, we will examine why two people can smell the same formula yet experience and describe it differently."}]},{"type":"heading","level":2,"text":"Next Lesson"},{"type":"heading","level":3,"text":"How We Experience Smell"},{"type":"paragraph","runs":[{"text":"The first lesson showed that perfume is constructed through decisions."}]},{"type":"paragraph","runs":[{"text":"The next lesson asks the other side of the question:"}]},{"type":"paragraph","runs":[{"text":"If the formula remains the same, why can the experience of smelling it differ from one person to another?","emphasis":true}]}]}$academy_complete$::jsonb),
      (17, 'id', $academy_complete${"heading":"Lanjutkan Pengamatan","sections":[{"type":"paragraph","runs":[{"text":"Sebelum melanjutkan ke Lesson 2, pilih satu parfum lain."}]},{"type":"paragraph","runs":[{"text":"Jangan melihat notes-nya."}]},{"type":"paragraph","runs":[{"text":"Tuliskan lima hal saja:"}]},{"type":"bullet_list","items":["temperature","texture","weight","space","movement."]},{"type":"paragraph","runs":[{"text":"Simpan catatan tersebut."}]},{"type":"paragraph","runs":[{"text":"Pada lesson berikutnya, kita akan melihat mengapa dua orang dapat mencium formula yang sama, tetapi mengalami dan menggambarkannya secara berbeda."}]},{"type":"heading","level":2,"text":"Lesson Selanjutnya"},{"type":"heading","level":3,"text":"How We Experience Smell"},{"type":"paragraph","runs":[{"text":"Lesson pertama menunjukkan bahwa parfum dibangun melalui keputusan."}]},{"type":"paragraph","runs":[{"text":"Lesson berikutnya akan membahas sisi lain dari pengalaman tersebut:"}]},{"type":"paragraph","runs":[{"text":"Jika formulanya sama, mengapa aroma yang dirasakan setiap orang dapat berbeda?","emphasis":true}]},{"type":"heading","level":3,"text":"Referensi pengembangan materi"},{"type":"paragraph","runs":[{"text":"Materi keselamatan dan penggunaan fragrance materials merujuk pada penjelasan resmi International Fragrance Association mengenai proses pembuatan fragrance, IFRA Standards, serta tanggung jawab perusahaan atas keselamatan dan kepatuhan finished products."}]}]}$academy_complete$::jsonb)
  ) as source(position,locale,content)
  join public.academy_lesson_blocks b on b.lesson_id=target_lesson_id and b.position=source.position
  where bt.block_id=b.id and bt.locale=source.locale;

  if (select count(*) from public.academy_lesson_blocks where lesson_id=target_lesson_id) <> 17 then raise exception 'Expected 17 lesson blocks'; end if;
end;
$academy_lesson_complete$;

commit;
